/* ======================= FORMAT ======================= */
const LOC = () => ({ id: 'id-ID', en: 'en-US', ar: 'ar-u-ca-gregory-nu-latn' })[S.lang];
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const fN = (v, o) => (v == null || !isFinite(v)) ? '—' : new Intl.NumberFormat(LOC(), o).format(v);
const fC = v => fN(v, { notation: 'compact', maximumFractionDigits: 1 });
const money = (v, full) => (v == null || !isFinite(v)) ? '—' : 'Rp ' + (full ? fN(Math.round(v)) : fN(v, { notation: 'compact', maximumFractionDigits: v >= 1e9 ? 2 : 1 }));
const pct = (v, d = 1) => (v == null || !isFinite(v)) ? '—' : fN(v, { maximumFractionDigits: d }) + '%';
const fD = (ts, o) => new Intl.DateTimeFormat(LOC(), o || { day: 'numeric', month: 'short', year: 'numeric' }).format(ts);
const fDT = ts => new Intl.DateTimeFormat(LOC(), { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' }).format(ts);
function rel(ts) { const d = (ts - nowTs()) / 1000, a = Math.abs(d); const r = new Intl.RelativeTimeFormat(LOC(), { numeric: 'auto', style: 'short' }); if (a < 45) return t('just_now'); if (a < 3600) return r.format(Math.round(d / 60), 'minute'); if (a < 86400) return r.format(Math.round(d / 3600), 'hour'); if (a < 86400 * 30) return r.format(Math.round(d / 86400), 'day'); return fD(ts); }
