const ic = (n, c) => `<svg class="ic ${c || ''}" viewBox="0 0 24 24" aria-hidden="true"><path d="${IC[n] || IC.circle}"/></svg>`;
const DIRIC = ['chevR', 'chevL', 'arrowR', 'arrowur', 'send', 'undo', 'logout', 'external'];
const icd = (n, c) => ic(n, (c || '') + (DIRIC.includes(n) ? ' flip' : ''));

/* ======================= SMALL COMPONENTS ======================= */
function st(key) { const s = STATUS[key] || ['neu', 'circle', key, key, key]; return `<span class="st ${s[0]}">${ic(s[1])}${esc(L3(s.slice(2)))}</span>`; }
const stTone = key => (STATUS[key] || ['neu'])[0];
function ent(name, sub, color, mark) { return `<div class="ent"><div class="lg" style="background:${color || '#3A4F8F'}" aria-hidden="true">${esc(mark || initials(name))}</div><div style="min-width:0"><b>${esc(name)}</b>${sub ? `<span>${sub}</span>` : ''}</div></div>`; }
const prio = p => `<span class="prio ${p}"><i></i>${{ p1: L3(['Tinggi', 'High', 'عالية']), p2: L3(['Sedang', 'Medium', 'متوسطة']), p3: L3(['Rendah', 'Low', 'منخفضة']) }[p]}</span>`;
const mockmark = () => !DEMO ? '' : `<span class="mockmark" title="Demonstration data">${ic('flag', 'sm')}DEMO</span>`;
function crumbs(list) { return `<nav class="crumbs" aria-label="Breadcrumb">${list.map((c, i) => i === list.length - 1 ? `<span class="cur" aria-current="page">${esc(c[0])}</span>` : `<a href="#${c[1]}">${esc(c[0])}</a>${icd('chevR', 'sm')}`).join('')}</nav>`; }
function phead({ crumbs: cr, title, desc, actions, extra }) { return `${crumbs(cr)}<div class="phead"><div class="ttl"><h1>${esc(title)}</h1>${desc ? `<p>${esc(desc)}</p>` : ''}${extra || ''}</div>${actions ? `<div class="actions">${actions}</div>` : ''}</div>`; }
function permBtn(perm, html, attrs, cls) { const ok = can(perm); const off = S.ux === 'offline' && /data-mut/.test(attrs || ''); return `<button class="btn ${cls || ''}" ${ok && !off ? attrs : 'aria-disabled="true" data-tip="' + esc(ok ? t('offline') : t('no_perm_action') + ': ' + perm) + '"'}>${html}</button>`; }
function kpiRow(items) { return `<div class="kpis">${items.map(k => `<${k.route ? 'a href="#' + k.route + '" style="color:inherit;text-decoration:none"' : 'div'} class="kpi ${k.route ? 'btnlike' : ''}"><div class="k">${k.icon ? ic(k.icon, 'sm') : ''}${esc(k.k)}</div><div class="v">${k.v}</div>${k.d ? `<div class="d">${k.d}</div>` : ''}</${k.route ? 'a' : 'div'}>`).join('')}</div>`; }
const delta = (v, inv) => { const up = v >= 0; const good = inv ? !up : up; return `<span class="delta ${good ? 'up' : 'down'}">${up ? '▲' : '▼'} ${pct(Math.abs(v))}</span>`; };
function stateBlock(kind, opts = {}) {
  const m = { empty: ['inbox', t('empty_t'), t('empty_d'), ''], noresult: ['search', t('noresult_t'), t('noresult_d'), ''], error: ['alert', t('error_t'), t('error_d'), 'bad'], noperm: ['lock', t('no_perm_t'), t('no_perm_d'), 'warn'], offline: ['wifioff', L3(['Menunggu koneksi', 'Waiting for connection', 'بانتظار الاتصال']), t('offline_b'), 'warn'], unavailable: ['info', L3(['Belum tersedia', 'Not available', 'غير متاح']), L3(['Data resmi belum tersedia pada kontrak API aktif.', 'Official data is not available in the active API contract.', 'البيانات الرسمية غير متاحة في عقد API النشط.']), ''] }[kind] || ['info', t('empty_t'), t('empty_d'), ''];
  return `<div class="state ${m[3]}" role="status"><div class="sic">${ic(m[0], 'lg')}</div><h4>${esc(opts.title || m[1])}</h4><p>${esc(opts.desc || m[2])}</p>${kind === 'error' ? `<button class="btn sm" data-act="ux" data-v="normal">${ic('refresh')}${t('retry')}</button>` : ''}${kind === 'noresult' && opts.tbl ? `<button class="btn sm" data-act="tbl-reset" data-tbl="${opts.tbl}">${t('reset_filters')}</button>` : ''}${opts.cta || ''}</div>`;
}
function skel(n = 5) { return `<div style="padding:14px;display:grid;gap:14px" aria-busy="true" aria-label="${t('loading')}">${Array.from({ length: n }, (_, i) => `<div style="display:flex;gap:12px;align-items:center"><div class="skel" style="width:32px;height:32px;border-radius:8px"></div><div style="flex:1;display:grid;gap:6px"><div class="skel" style="width:${40 + (i * 17) % 40}%"></div><div class="skel" style="width:${20 + (i * 11) % 30}%;height:9px"></div></div><div class="skel" style="width:70px"></div></div>`).join('')}</div>`; }
/* gate: apply global UX-state preview to a data panel */
function gate(html, n) { if (S.ux === 'loading') return skel(n || 4); if (S.ux === 'empty') return stateBlock('empty'); if (S.ux === 'error') return stateBlock('error'); return html; }
function lifeBar(flow, cur, exc) { const i = flow.indexOf(cur); return `<div class="life" role="list">${flow.map((s, k) => `<div role="listitem" class="stp ${exc ? (k <= Math.max(0, i) ? 'done' : '') : k < i ? 'done' : k === i ? 'cur' : ''}"><b>${esc(L3((STATUS[s] || [0, 0, s, s, s]).slice(2)))}</b>${k < i || (k === i && !exc) ? (k === i ? '<span>' + L3(['Saat ini', 'Current', 'الحالي']) + '</span>' : '<span>✓</span>') : '<span>—</span>'}</div>`).join('')}${exc ? `<div class="stp exc cur" role="listitem"><b style="color:var(--bad)">${esc(L3(STATUS[exc].slice(2)))}</b><span>${L3(['Pengecualian', 'Exception', 'استثناء'])}</span></div>` : ''}</div>`; }

/* ======================= CHARTS (SVG, hover-ready) ======================= */
function niceMax(v) { const p = Math.pow(10, Math.floor(Math.log10(v || 1))); const n = v / p; return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 2.5 ? 2.5 : n <= 5 ? 5 : 10) * p; }
function areaChart(data, { key, fmt = fC, h = 190, color = 'var(--accent)', label = '' }) {
  const W = 640, H = h, pl = 46, pr = 10, pt = 10, pb = 24; const vals = data.map(d => d[key]); const max = niceMax(Math.max(...vals) * 1.08); const x = i => pl + i * (W - pl - pr) / (data.length - 1); const y = v => pt + (H - pt - pb) * (1 - v / max);
  const line = vals.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(''); const area = line + `L${x(vals.length - 1)},${y(0)}L${x(0)},${y(0)}Z`;
  const ticks = [0, .5, 1].map(f => max * f); const gid = 'g' + Math.random().toString(36).slice(2, 7); const cw = (W - pl - pr) / (data.length - 1);
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)}"><defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="${color}" stop-opacity=".22"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>
  <g class="grid">${ticks.map(v => `<line x1="${pl}" x2="${W - pr}" y1="${y(v)}" y2="${y(v)}"/>`).join('')}</g>
  ${ticks.map(v => `<text x="${pl - 6}" y="${y(v) + 3.5}" text-anchor="end">${esc(fmt(v))}</text>`).join('')}
  ${[0, Math.floor(data.length / 2), data.length - 1].map(i => `<text x="${x(i)}" y="${H - 6}" text-anchor="${i === 0 ? 'start' : i === data.length - 1 ? 'end' : 'middle'}">${esc(fD(data[i].ts, { day: 'numeric', month: 'short' }))}</text>`).join('')}
  <path d="${area}" fill="url(#${gid})"/><path d="${line}" fill="none" stroke="${color}" stroke-width="2" stroke-linejoin="round"/>
  <circle cx="${x(vals.length - 1)}" cy="${y(vals[vals.length - 1])}" r="4" fill="${color}" stroke="var(--surface)" stroke-width="2"/>
  ${vals.map((v, i) => `<g class="hc" data-tip="${esc(fD(data[i].ts, { day: 'numeric', month: 'short' }) + ' · ' + fmt(v))}"><rect x="${x(i) - cw / 2}" y="${pt}" width="${cw}" height="${H - pt - pb}" fill="transparent"/><line x1="${x(i)}" x2="${x(i)}" y1="${pt}" y2="${H - pb}" stroke="var(--line-strong)" stroke-dasharray="3 3"/><circle cx="${x(i)}" cy="${y(v)}" r="4" fill="var(--surface)" stroke="${color}" stroke-width="2"/></g>`).join('')}
  </svg>`;
}
function barChart(data, { key, fmt = fC, h = 170, color = 'var(--s1)', label = '' }) {
  const W = 640, H = h, pl = 40, pr = 6, pt = 8, pb = 22; const vals = data.map(d => d[key]); const max = niceMax(Math.max(...vals) * 1.05); const bw = (W - pl - pr) / vals.length; const y = v => pt + (H - pt - pb) * (1 - v / max); const ticks = [0, .5, 1].map(f => max * f);
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)}"><g class="grid">${ticks.map(v => `<line x1="${pl}" x2="${W - pr}" y1="${y(v)}" y2="${y(v)}"/>`).join('')}</g>${ticks.map(v => `<text x="${pl - 6}" y="${y(v) + 3.5}" text-anchor="end">${esc(fmt(v))}</text>`).join('')}
  ${vals.map((v, i) => { const bx = pl + i * bw + 1.5, w = Math.max(2, bw - 3), yy = y(v), hh = y(0) - yy; return `<g class="hb" data-tip="${esc(fD(data[i].ts, { day: 'numeric', month: 'short' }) + ' · ' + fmt(v))}"><rect x="${pl + i * bw}" y="${pt}" width="${bw}" height="${H - pt - pb}" fill="transparent"/><path d="M${bx},${y(0)}V${yy + Math.min(3, hh)}q0,-3 3,-3h${w - 6}q3,0 3,3V${y(0)}Z" fill="${color}"/></g>`; }).join('')}
  ${[0, data.length - 1].map(i => `<text x="${pl + i * bw + bw / 2}" y="${H - 6}" text-anchor="${i ? 'end' : 'start'}">${esc(fD(data[i].ts, { day: 'numeric', month: 'short' }))}</text>`).join('')}</svg>`;
}
function spark(vals, color = 'var(--accent)', w = 96, h = 28) { const max = Math.max(...vals), min = Math.min(...vals); const x = i => i * w / (vals.length - 1), y = v => h - 3 - (h - 6) * ((v - min) / ((max - min) || 1)); const d = vals.map((v, i) => `${i ? 'L' : 'M'}${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(''); return `<svg width="${w}" height="${h}" viewBox="0 0 ${w} ${h}" aria-hidden="true" style="overflow:visible"><path d="${d}" fill="none" stroke="${color}" stroke-width="1.6"/><circle cx="${x(vals.length - 1)}" cy="${y(vals[vals.length - 1])}" r="2.5" fill="${color}"/></svg>`; }
function hbars(rows, fmt = fC, color = 'var(--s1)') { const max = Math.max(...rows.map(r => r[1])) || 1; return `<div class="hbar">${rows.map(r => `<span style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(r[0])}</span><div class="bar" style="width:${Math.max(2, r[1] / max * 100)}%;background:${r[2] || color}" data-tip="${esc(r[0] + ' · ' + fmt(r[1]))}"></div><span class="val">${esc(fmt(r[1]))}</span>`).join('')}</div>`; }

