function decideApproval(id, v, reason) { const a = APPROVALS.find(x => x.id === id); const prev = a.status; a.status = v; a.fresh = false; a.history.push({ t: L3(['Keputusan: ', 'Decision: ', 'القرار: ']) + L3(STATUS[v].slice(2)), ts: nowTs(), tone: v === 'approved' ? 'ok' : v === 'rejected' ? 'bad' : 'warn', by: 'Admin Pusat (' + ROLES[S.role].label + ')', reason }); audit('Admin Pusat', 'approval.' + v, 'Approval/' + id + ' (' + a.title + ')', 'success', { before: '{ "status": "' + prev + '" }', after: '{ "status": "' + v + '" }', reason });
  if (v === 'approved' && a.type === 'legal_doc') { const tr = travelById(a.reqRef); if (tr) { tr.lic.forEach(l => { if (l.status !== 'verified') { l.status = 'verified'; l.exp = T0 + 3 * 365 * D; } }); tr.legal = 'verified'; if (tr.op === 'review') tr.op = 'active'; } }
  if (a.type === 'travel_verif') { const tr = travelById(a.reqRef); if (tr) { if (v === 'approved') { tr.lic.forEach(l => { if (l.status !== 'verified') { l.status = 'verified'; l.exp = nowTs() + 3 * 365 * D; } }); tr.legal = 'verified'; tr.op = 'active'; if (tr.sub.state === 'pending') tr.sub.state = 'active'; tr.verifiedAt = nowTs(); } else if (v === 'rejected') { tr.legal = 'rejected'; tr.op = 'inactive'; } else { tr.legal = 'under_review'; } } }
  if (a.type === 'vendor_verif') { const vd = VENDORS.find(x => x.id === a.reqRef); if (vd) { if (v === 'approved') { vd.verif = 'verified'; vd.status = 'active'; } else if (v === 'rejected') { vd.verif = 'rejected'; } else vd.verif = 'needs_revision'; } }
  if (a.type === 'withdrawal') { const w = WITHDRAWALS.find(w => w.party === a.requester && w.state === 'pending'); if (w) w.state = v === 'approved' ? 'approved' : v === 'rejected' ? 'rejected' : 'hold'; }
  toast(v === 'approved' ? 'ok' : v === 'rejected' ? 'bad' : 'warn', L3(STATUS[v].slice(2)) + ' · ' + id, L3(['Tercatat di Audit Log · resource terkait diperbarui', 'Recorded in Audit Log · related resource updated', 'سُجّل في سجل التدقيق']), '/compliance/audit'); rerender(); }

