function licChips(tr) { return `<div class="lic">${tr.lic.map(l => `<span class="chip ${l.status === 'verified' ? 'v' : ['expired', 'rejected'].includes(l.status) ? 'x' : 'p'}" title="${esc(l.type + ' · ' + L3(STATUS[l.status].slice(2)))}">${l.type}${l.status === 'verified' ? ' ✓' : l.status === 'expiring' ? ' ⏱' : ['expired', 'rejected'].includes(l.status) ? ' ✕' : ' …'}</span>`).join('')}</div>`; }
