  const html = `<div class="page">${phead({ crumbs: [[t('g_eko'), '/travel'], ['Travel', '/travel'], [t('tr_title'), '/travel']], title: t('tr_title'), desc: t('tr_desc'), actions: `<button class="btn" data-act="preview-data">${ic('eye')}${t('preview')}</button><button class="btn" data-act="export" data-what="Travel">${ic('download')}${t('export')}</button>${permBtn('travel.create', ic('plus') + t('add_travel'), 'data-act="add-travel" data-mut', 'primary')}` })}
  ${gate(kpiRow([{ k: t('k_total'), v: fN(TRAVELS.length), d: `${TRAVELS.filter(x => x.op === 'active').length} ${L3(['aktif', 'active', 'نشطة'])} · ${mockmark()}`, icon: 'building' }, { k: t('k_verified'), v: fN(TRAVELS.filter(x => x.legal === 'verified' || x.legal === 'expiring').length), d: `${TRAVELS.filter(x => x.legal === 'expiring').length} ${L3(['segera expired', 'expiring soon', 'قاربت على الانتهاء'])}`, icon: 'filecheck', route: '/travel/legal' }, { k: t('k_waiting'), v: fN(TRAVELS.filter(x => x.legal === 'under_review').length), d: `<a href="#/approval">${L3(['Buka Approval Center', 'Open Approval Center', 'مركز الموافقات'])} →</a>`, icon: 'clock' }, { k: t('k_branch'), v: fN(branches), d: L3(['Default 2 cabang / subscription', 'Default 2 branches / subscription', 'فرعان افتراضياً']), icon: 'map', route: '/travel/branches' }]), 2)}
  <section class="panel" style="margin-top:14px">${tb}</section>
  <div class="grid g3" style="margin-top:14px">${pnl(L3(['Distribusi payment flow', 'Payment flow split', 'توزيع مسار الدفع']), hbars([['VIA_SEGALOKA', TRAVELS.filter(x => x.payMode === 'VIA_SEGALOKA').length], ['DIRECT_TO_TRAVEL', TRAVELS.filter(x => x.payMode === 'DIRECT_TO_TRAVEL').length]], fN), { icon: 'repeat' })}${pnl(L3(['Plan subscription', 'Subscription plans', 'خطط الاشتراك']), hbars(['Starter', 'Growth', 'Scale'].map(p => [p, TRAVELS.filter(x => x.sub.plan === p).length]), fN), { icon: 'refresh' })}${pnl(L3(['Izin per layanan', 'Licenses by service', 'التراخيص حسب الخدمة']), hbars(['BPW', 'PPIU', 'PIHK'].map(p => [p, TRAVELS.filter(x => x.lic.some(l => l.type === p)).length]), fN), { icon: 'filecheck' })}</div></div>`;
