  const p = CC_TRAVEL_API.pagination || { limit: 25, offset: 0, total: 0 }; const from = p.total ? p.offset + 1 : 0; const to = Math.min(p.offset + p.limit, p.total); const total = '<span class="muted">' + L3(['Menampilkan', 'Showing', 'عرض']) + ' ' + fN(from) + '–' + fN(to) + ' ' + L3(['dari', 'of', 'من']) + ' ' + fN(p.total) + '</span>'; const pager = state === 'ready' ? '<div class="pager"><span>' + total + '</span><span class="sp"></span><button class="btn sm" data-act="cc-travel-prev" ' + (p.offset <= 0 ? 'disabled' : '') + '>' + t('prev') + '</button><button class="btn sm" data-act="cc-travel-next" ' + (p.offset + p.limit >= p.total ? 'disabled' : '') + '>' + t('next') + '</button></div>' : '';
