  const filters = '<div class="tabs" role="tablist">' + [['all', 'f_all'], ['active', 'f_active'], ['review', 'f_review'], ['inactive', 'f_inactive']].map(([value, label]) => '<button class="tab" aria-selected="' + (CC_TRAVEL_FILTER === value ? 'true' : 'false') + '" data-v="' + value + '" data-act="cc-travel-filter">' + t(label) + '</button>').join('') + '</div>';
