route('/travel', PAGES.travelApiDir);
A['cc-travel-refresh'] = () => ccLoadTravels(document.getElementById('cc-travel-q')?.value || '', CC_TRAVEL_API.pagination?.offset || 0, CC_TRAVEL_FILTER);
A['cc-travel-export'] = async () => { const query = new URLSearchParams(); const input = document.getElementById('cc-travel-q'); if (input?.value.trim()) query.set('q', input.value.trim()); if (CC_TRAVEL_FILTER !== 'all') query.set('status', CC_TRAVEL_FILTER); try { const response = await fetch('/bff/control-center/travels/export.pdf' + (query.toString() ? '?' + query : ''), { credentials: 'same-origin', cache: 'no-store' }); if (!response.ok || response.headers.get('content-type')?.split(';')[0] !== 'application/pdf') throw new Error('TRAVEL_EXPORT_UNAVAILABLE'); const blob = await response.blob(); if (!blob.size) throw new Error('TRAVEL_EXPORT_EMPTY'); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'Segaloka-Laporan-Travel-' + new Date().toISOString().slice(0, 10) + '.pdf'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (error) { toast('bad', L3(['Export gagal', 'Export failed', 'فشل التصدير']), error.message || 'TRAVEL_EXPORT_UNAVAILABLE'); } };
A['cc-travel-export'] = async () => { const query = new URLSearchParams({ lang: ['id', 'en', 'ar'].includes(S.lang) ? S.lang : 'id' }); const input = document.getElementById('cc-travel-q'); if (input?.value.trim()) query.set('q', input.value.trim()); if (CC_TRAVEL_FILTER !== 'all') query.set('status', CC_TRAVEL_FILTER); try { const response = await fetch('/bff/control-center/travels/export.pdf?' + query.toString(), { credentials: 'same-origin', cache: 'no-store' }); if (!response.ok || response.headers.get('content-type')?.split(';')[0] !== 'application/pdf') throw new Error('TRAVEL_EXPORT_UNAVAILABLE'); const blob = await response.blob(); if (!blob.size) throw new Error('TRAVEL_EXPORT_EMPTY'); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'Segaloka-Laporan-Travel-' + new Date().toISOString().slice(0, 10) + '.pdf'; document.body.appendChild(link); link.click(); link.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); } catch (error) { toast('bad', L3(['Export gagal', 'Export failed', 'فشل التصدير']), error.message || 'TRAVEL_EXPORT_UNAVAILABLE'); } };
A['cc-travel-more-filter'] = () => modal({ title: t('filters_more'), body: '<div class="field"><label for="cc-extra-status">' + t('status') + '</label><select id="cc-extra-status"><option value="all" ' + (CC_TRAVEL_FILTER === 'all' ? 'selected' : '') + '>' + t('all') + '</option><option value="active" ' + (CC_TRAVEL_FILTER === 'active' ? 'selected' : '') + '>' + t('f_active') + '</option><option value="review" ' + (CC_TRAVEL_FILTER === 'review' ? 'selected' : '') + '>' + t('f_review') + '</option><option value="inactive" ' + (CC_TRAVEL_FILTER === 'inactive' ? 'selected' : '') + '>' + t('f_inactive') + '</option></select></div>', foot: '<button class="btn" data-act="cc-travel-reset-filter">' + L3(['Reset', 'Reset', 'إعادة ضبط']) + '</button><button class="btn" data-act="close">' + t('cancel') + '</button><button class="btn primary" data-act="cc-travel-apply-filter">' + t('save') + '</button>' });
