A['cc-travel-row-menu'] = el => { const id = el.dataset.id; popAt(el, '<div class="menu"><button class="mi" data-act="nav" data-r="/travel/' + encodeURIComponent(id) + '">' + ic('eye', 'sm') + t('open_detail') + '</button><button class="mi" data-act="nav" data-r="/travel/' + encodeURIComponent(id) + '/legal">' + ic('filecheck', 'sm') + t('t_legal') + '</button><button class="mi" data-act="nav" data-r="/travel/' + encodeURIComponent(id) + '/branches">' + ic('map', 'sm') + t('t_branch') + '</button></div>'); };
