/* ---------- Payment detail ---------- */
route('/finance/payment/:id', p => {
  const x = PAYMENTS.find(y => y.id === p.id); if (!x) return { html: `<div class="page">${stateBlock('noresult', { title: 'Payment tidak ditemukan', desc: p.id })}</div>` };
  const b = bookingById(x.booking); const tr = travelById(x.travel); const stl = SETTLEMENTS.find(s => s.travel === x.travel);
  const ev = [['payment.created', x.ts - 20 * 60e3, 'info', 'Control Center · checkout'], ['charge.pending · VA issued', x.ts - 19 * 60e3, 'info', x.provider + ' API · 201'], ...(x.status === 'paid' || x.status === 'refunded' ? [['webhook payment.paid', x.ts, 'ok', x.provider + ' → /webhooks/' + x.provider.toLowerCase() + ' · sig ✓ · idempotent'], ['ledger.posted', x.ts + 2e3, 'ok', 'Ledger · ' + (x.flow === 'VIA_SEGALOKA' ? 'credit tenant balance' : 'record only')], ['booking.state → ' + (b ? b.state : 'confirmed'), x.ts + 3e3, 'ok', 'Booking service']] : []), ...(x.status === 'failed' ? [['webhook payment.failed', x.ts, 'bad', 'Issuer declined (51)']] : []), ...(x.status === 'expired' ? [['payment.expired', x.ts + 24 * H, 'warn', 'VA TTL 24 jam']] : []), ...(x.recon === 'reconciled' ? [['reconciliation.matched', x.ts + 20 * H, 'ok', 'Bank statement REC-260923']] : x.recon === 'unmatched' ? [['reconciliation.unmatched', x.ts + 20 * H, 'warn', L3(['Tidak ditemukan di mutasi bank', 'Not found in bank statement', 'غير موجود'])]] : x.recon === 'mismatch' ? [['reconciliation.mismatch', x.ts + 20 * H, 'bad', 'Selisih Rp 2.500 (biaya admin bank)']] : [])];
  const html = `<div class="page">${crumbs([[t('g_fin'), '/finance'], [t('fin_tx'), '/finance/transactions'], [x.id, '']])}
  <div class="phead"><div class="ttl"><h1 class="mono" style="font-family:var(--font-mono)">${x.id}</h1><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px;align-items:center"><span class="muted" style="font-size:12px">Payment</span>${st(x.status)}<span class="muted" style="font-size:12px">Reconciliation</span>${st(x.recon)}${stl && x.flow === 'VIA_SEGALOKA' ? `<span class="muted" style="font-size:12px">Settlement</span>${st(stl.state)}` : ''}<span class="chip mono">${x.flow}</span></div></div><div class="actions">${x.status === 'paid' ? permBtn('finance.refund', ic('undo') + L3(['Ajukan refund', 'Request refund', 'طلب استرداد']), `data-act="pay-refund" data-id="${x.id}" data-mut`, '') : ''}${permBtn('finance.reconcile', ic('scale') + L3(['Match manual', 'Manual match', 'مطابقة يدوية']), `data-act="pay-match" data-id="${x.id}" data-mut`, '')}</div></div>
  <div class="grid g12"><div class="c7" style="display:grid;gap:14px;align-content:start">${pnl('Detail', `<dl class="dl"><dt>Amount</dt><dd><b class="tnum" style="font-size:18px;font-family:var(--font-display)">${money(x.amount, true)}</b></dd><dt>Payer</dt><dd>${esc(trvName(x.payer))} <span class="mono muted">${x.payer}</span></dd><dt>Booking</dt><dd><a href="#/booking/${x.booking}" class="mono">${x.booking}</a> ${b ? st(b.state) : ''}</dd><dt>Travel</dt><dd><a href="#/travel/${tr.id}">${esc(tr.name)}</a></dd><dt>Provider</dt><dd>${esc(x.provider)}</dd><dt>Channel</dt><dd>${esc(x.channel)}</dd><dt>Transaction ref</dt><dd class="mono">${esc(x.ref)} <button class="btn sm ghost" data-act="copy" data-v="${esc(x.ref)}" aria-label="Copy">${ic('copy', 'sm')}</button></dd><dt>MDR</dt><dd class="tnum">${money(x.fee, true)}</dd><dt>Created</dt><dd>${fDT(x.ts - 20 * 60e3)}</dd><dt>Paid at</dt><dd>${x.status === 'paid' || x.status === 'refunded' ? fDT(x.ts) : '—'}</dd></dl>`, { icon: 'card' })}</div>
  <div class="c5">${pnl('Webhook / event timeline', `<ul class="tl">${ev.map(e => `<li><span class="dotc ${e[2]}"></span><b class="mono" style="font-weight:550;font-size:12.5px">${esc(e[0])}</b><div class="m">${esc(fDT(e[1]))} · ${esc(e[3])}</div></li>`).join('')}</ul>`, { icon: 'zap' })}</div></div></div>`;
  return { html };
});

