const dirPage = ({ nav, title, desc, actions, kpis, tableId, cfg, extra, note }) => { const n = NAVIDX[nav]; const tr = navTrail(nav); return { html: `<div class="page">${phead({ crumbs: tr.map(x => [x[0], x[1] || S.route]), title: title || t(nav), desc, actions: (actions || '') + `<button class="btn" data-act="export" data-what="${esc(t(nav))}">${ic('download')}Export</button>` })}${note ? `<div class="banner info" style="border:1px solid var(--info-line);border-radius:10px;margin-bottom:14px">${ic('info')}<span>${note}</span></div>` : ''}${kpis ? gate(kpiRow(kpis), 2) : ''}<section class="panel" style="${kpis ? 'margin-top:14px' : ''}">${defTable(tableId, cfg)}</section>${extra || ''}</div>` }; };
const lvlNote = () => `${mockmark()} ${L3(['Fungsional — data simulasi', 'Functional — mock data', 'وظيفي — بيانات تجريبية'])}`;

let CC_BRANCHES = { state: 'idle', items: [], pagination: null, error: '', httpStatus: 0 };
async function ccLoadBranches(query = '', offset = 0) {
  CC_BRANCHES = { ...CC_BRANCHES, state: 'loading', error: '', httpStatus: 0 }; rerender();
  try {
    const p = new URLSearchParams({ limit: '25', offset: String(offset) }); if (query.trim()) p.set('q', query.trim());
    const response = await fetch('/bff/control-center/travel-branches?' + p, { credentials: 'same-origin', cache: 'no-store' });
    const result = await response.json().catch(() => ({}));
    if (!response.ok) { const e = new Error(result.code || 'TRAVEL_BRANCH_UNAVAILABLE'); e.status = response.status; throw e; }
    if (result.source !== 'postgresql' || !Array.isArray(result.items) || !result.pagination) throw new Error('TRAVEL_BRANCH_INVALID');
    CC_BRANCHES = { state: 'ready', items: result.items, pagination: result.pagination, error: '', httpStatus: response.status };
  } catch (error) { CC_BRANCHES = { ...CC_BRANCHES, state: 'error', error: error.message || 'TRAVEL_BRANCH_UNAVAILABLE', httpStatus: error.status || 0 }; }
  rerender();
}
function travelBranchesApiPage() {
  const s = CC_BRANCHES, p = s.pagination || { limit: 25, offset: 0, total: 0 };
  let body = s.state === 'loading' ? stateBlock('loading', { title: L3(['Memuat cabang', 'Loading branches', 'جار تحميل الفروع']) }) : '';
  if (s.state === 'error') body = stateBlock('error', { title: s.httpStatus === 401 ? L3(['Sesi diperlukan', 'Session required', 'الجلسة مطلوبة']) : s.httpStatus === 403 ? L3(['Akses ditolak', 'Access denied', 'تم رفض الوصول']) : L3(['Data cabang tidak tersedia', 'Branch data unavailable', 'بيانات الفروع غير متاحة']), desc: L3(['Tidak ada data simulasi yang ditampilkan.', 'No simulated data is shown.', 'لا تُعرض بيانات تجريبية.']) });
  else if (s.state === 'ready' && !s.items.length) body = stateBlock('empty', { title: L3(['Belum ada cabang', 'No branches yet', 'لا فروع']), desc: L3(['Tidak ada cabang pada sumber data resmi.', 'No branches exist in the official data source.', 'لا توجد فروع في مصدر البيانات الرسمي.']) });
  else if (s.state === 'ready') body = '<div class="tbl-wrap"><table class="t"><thead><tr><th>' + L3(['Nama cabang', 'Branch name', 'اسم الفرع']) + '</th><th>' + L3(['Kode', 'Code', 'الرمز']) + '</th><th>Travel</th><th>' + L3(['Status', 'Status', 'الحالة']) + '</th></tr></thead><tbody>' + s.items.map(b => '<tr><td><a href="#/travel/' + encodeURIComponent(b.organizationId || b.parentOrganizationId || '') + '/branches"><b>' + esc(b.branchName || b.name || '—') + '</b></a></td><td class="mono">' + esc(b.branchCode || '—') + '</td><td class="mono">' + esc(b.organizationId || b.parentOrganizationId || '—') + '</td><td>' + st(b.status) + '</td></tr>').join('') + '</tbody></table></div>';
  const from = p.total ? p.offset + 1 : 0, to = Math.min(p.offset + p.limit, p.total); const pager = s.state === 'ready' ? '<div class="pager"><span class="muted">' + L3(['Menampilkan', 'Showing', 'عرض']) + ' ' + fN(from) + '–' + fN(to) + ' ' + L3(['dari', 'of', 'من']) + ' ' + fN(p.total) + '</span><span class="sp"></span><button class="btn sm" data-act="cc-branches-prev" ' + (p.offset <= 0 ? 'disabled' : '') + '>' + t('prev') + '</button><button class="btn sm" data-act="cc-branches-next" ' + (p.offset + p.limit >= p.total ? 'disabled' : '') + '>' + t('next') + '</button></div>' : '';
  return { html: '<div class="page">' + phead({ crumbs: [[t('g_eko'), '/travel'], [t('travel'), '/travel'], [L3(['Cabang Travel', 'Travel branches', 'فروع السفر']), '']], title: L3(['Cabang Travel', 'Travel branches', 'فروع السفر']), desc: L3(['Cabang resmi dari PostgreSQL melalui API Segaloka.', 'Official branches from PostgreSQL through the Segaloka API.', 'الفروع الرسمية من PostgreSQL عبر واجهة Segaloka.']), actions: '<button class="btn" data-act="cc-branches-refresh">' + t('cc_refresh') + '</button>' }) + '<section class="panel"><div class="toolbar"><label class="input">' + ic('search', 'sm') + '<input id="cc-branches-q" type="search" placeholder="' + L3(['Cari cabang atau kode', 'Search branch or code', 'ابحث عن فرع أو رمز']) + '"></label></div>' + body + pager + '</section></div>', mount() { const input = document.getElementById('cc-branches-q'); if (input) input.addEventListener('change', () => ccLoadBranches(input.value, 0)); if (s.state === 'idle') ccLoadBranches(); } };
}
route('/travel/branches', travelBranchesApiPage);
A['cc-branches-refresh'] = () => ccLoadBranches(document.getElementById('cc-branches-q')?.value || '', CC_BRANCHES.pagination?.offset || 0);
A['cc-branches-prev'] = () => ccLoadBranches(document.getElementById('cc-branches-q')?.value || '', Math.max(0, (CC_BRANCHES.pagination?.offset || 0) - (CC_BRANCHES.pagination?.limit || 25)));
A['cc-branches-next'] = () => ccLoadBranches(document.getElementById('cc-branches-q')?.value || '', (CC_BRANCHES.pagination?.offset || 0) + (CC_BRANCHES.pagination?.limit || 25));

