let CC_VENDOR_API = { state: 'idle', items: [], pagination: null };
async function ccLoadVendors(query = '') {
  CC_VENDOR_API = { ...CC_VENDOR_API, state: 'loading' }; rerender();
  try {
    const p = new URLSearchParams({ limit: '100', offset: '0' }); if (query.trim()) p.set('q', query.trim());
    const response = await fetch('/bff/control-center/vendors?' + p, { credentials: 'same-origin', cache: 'no-store' });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.source !== 'postgresql' || !Array.isArray(result.items)) throw new Error(result.code || 'VENDOR_API_UNAVAILABLE');
    CC_VENDOR_API = { state: 'ready', items: result.items, pagination: result.pagination || null };
  } catch (_) { CC_VENDOR_API = { state: 'error', items: [], pagination: null }; }
  rerender();
}
route('/vendor', () => {
  const body = CC_VENDOR_API.state === 'loading' ? stateBlock('loading', { title: 'Memuat data Vendor', desc: 'Mengambil data resmi dari API Segaloka.' }) : CC_VENDOR_API.state === 'error' ? stateBlock('error', { title: 'Data Vendor tidak tersedia', desc: 'API Vendor gagal diakses. Tidak ada data simulasi yang ditampilkan.' }) : CC_VENDOR_API.items.length ? '<div class="tbl-wrap"><table class="t"><thead><tr><th>ID</th><th>Nama organisasi</th><th>Status</th><th class="r">Membership</th></tr></thead><tbody>' + CC_VENDOR_API.items.map(v => '<tr><td class="mono">' + esc(v.id) + '</td><td><b>' + esc(v.name) + '</b></td><td>' + st(v.status) + '</td><td class="r tnum">' + fN(v.membershipCount) + '</td></tr>').join('') + '</tbody></table></div>' : stateBlock('empty', { title: 'Belum ada Vendor', desc: 'Tidak ada organisasi Vendor pada sumber data resmi.' });
  const html = '<div class="page">' + phead({ crumbs: [[t('g_eko'), '/vendor'], [t('vendor'), '/vendor']], title: L3(['Manajemen Vendor','Vendor Management','إدارة الموردين']), desc: L3(['Daftar organisasi Vendor dari PostgreSQL melalui API Segaloka.','Vendor organizations from PostgreSQL through the Segaloka API.','قائمة منظمات الموردين من PostgreSQL عبر Segaloka API.']), actions: '<button class="btn" data-act="cc-vendor-refresh">' + t('cc_refresh') + '</button>' }) + '<section class="panel"><div class="toolbar"><label class="input">' + ic('search', 'sm') + '<input id="cc-vendor-q" type="search" placeholder="' + L3(['Cari ID atau nama Vendor','Search Vendor ID or name','ابحث عن معرف أو اسم المورد']) + '"></label></div>' + body + '</section></div>';
  return { html, mount() { const input = document.getElementById('cc-vendor-q'); if (input) input.addEventListener('change', () => ccLoadVendors(input.value)); if (CC_VENDOR_API.state === 'idle') ccLoadVendors(); } };
});
