const VTABS = ['identity', 'category', 'verification', 'products', 'orders', 'finance', 'withdrawal', 'performance', 'documents', 'activity'];
function vendorDetail(p) { const v = VENDORS.find(x => x.id === p.id); if (!v) return { html: `<div class="page">${stateBlock('noresult')}</div>` }; const tab = VTABS.includes(p.tab) ? p.tab : 'identity'; const wd = WITHDRAWALS.filter(w => w.ref === v.id);
  const lbl = { identity: L3(['Identitas', 'Identity', 'الهوية']), category: L3(['Kategori', 'Category', 'الفئة']), verification: L3(['Verifikasi', 'Verification', 'التوثيق']), products: L3(['Produk & Layanan', 'Products & Services', 'المنتجات']), orders: L3(['Pesanan', 'Orders', 'الطلبات']), finance: L3(['Keuangan', 'Finance', 'المالية']), withdrawal: L3(['Penarikan', 'Withdrawal', 'السحب']), performance: L3(['Performa', 'Performance', 'الأداء']), documents: L3(['Dokumen', 'Documents', 'المستندات']), activity: L3(['Aktivitas', 'Activity', 'النشاط']) };
  let body = '';
  if (tab === 'identity') body = pnl(lbl.identity, `<dl class="dl"><dt>Vendor ID</dt><dd class="mono">${v.id}</dd><dt>${L3(['Negara', 'Country', 'البلد'])}</dt><dd>${esc(v.country)}</dd><dt>${L3(['Bergabung', 'Joined', 'انضم'])}</dt><dd>${fD(v.joined)}</dd><dt>Rating</dt><dd>★ ${v.rating}</dd><dt>${L3(['Pembayaran', 'Payments', 'المدفوعات'])}</dt><dd>${L3(['Melalui Segaloka; withdrawal mengikuti transaksi/pembelian yang selesai.', 'Through Segaloka; withdrawal follows completed transactions/purchases.', 'عبر Segaloka.'])}</dd></dl>`, { icon: 'store' });
  else if (tab === 'category') body = pnl(lbl.category, `<div style="display:flex;gap:8px;flex-wrap:wrap">${VENDOR_CATS.map(c => `<span class="chip" style="${v.cats.includes(c) ? 'background:var(--accent-soft);color:var(--accent-text);font-weight:600' : ''}">${v.cats.includes(c) ? '✓ ' : ''}${c}</span>`).join('')}</div>`, { icon: 'grid' });
  else if (tab === 'verification') body = pnl(lbl.verification, `${lifeBar(['draft', 'submitted', 'under_review', 'verified'], v.verif === 'rejected' ? 'under_review' : v.verif, v.verif === 'rejected' ? 'rejected' : null)}<p class="muted" style="margin:12px 0 0">${L3(['Keputusan verifikasi dilakukan di', 'Verification decisions are made in', 'تُتخذ القرارات في'])} <a href="#/approval">Approval Center</a>.</p>`, { icon: 'shieldc' });
  else if (tab === 'withdrawal') body = pnl('Withdrawal', wd.length ? `<div class="list" style="margin:-14px">${wd.map(w => `<div class="li"><span class="body"><b class="mono">${w.id}</b><span class="sub">${esc(w.basis)} · ${rel(w.ts)}</span></span><b class="tnum">${money(w.amount)}</b>${st(w.state)}</div>`).join('')}</div>` : stateBlock('empty'), { icon: 'arrowur' });
  else if (tab === 'performance') body = `<div class="kpis">${[[L3(['Pesanan 30 hari', 'Orders 30d', 'الطلبات خلال 30 يوماً']), fN(v.orders30)], [L3(['GMV 30 hari', 'GMV 30d', 'إجمالي قيمة البضائع خلال 30 يوماً']), money(v.gmv30)], ['SLA', v.sla + '%'], [L3(['Rating', 'Rating', 'التقييم']), '★ ' + v.rating]].map(k => `<div class="kpi"><div class="k">${k[0]}</div><div class="v">${k[1]}</div></div>`).join('')}</div>`;
  else body = vendorTab(v, tab);
  return { html: `<div class="page">${crumbs([[t('g_eko'), '/vendor'], [L3(['Vendor', 'Vendor', 'المورّد']), '/vendor'], [v.name, '']])}<div class="phead"><div class="ttl" style="display:flex;gap:14px"><div class="ent"><div class="lg" style="background:${v.color};width:52px;height:52px;border-radius:12px">${initials(v.name)}</div></div><div><h1>${esc(v.name)}</h1><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px"><span class="chip mono">${v.id}</span>${st(v.status)}${st(v.verif)}${v.cats.map(c => `<span class="chip">${c}</span>`).join('')}</div></div></div><div class="actions"><a class="btn" href="#/omni/inbox">${ic('msg')}${t('contact_travel')}</a>${permBtn('vendor.suspend', ic(v.status === 'inactive' ? 'play' : 'ban') + (v.status === 'inactive' ? t('reactivate') : L3(['Tangguhkan vendor', 'Suspend vendor', 'تعليق المورّد'])), `data-act="vendor-status" data-id="${v.id}" data-mut`, v.status === 'inactive' ? 'okb' : 'badb')}</div></div><div class="kpis" style="margin-bottom:12px">${[['Order 30d', fN(v.orders30)], ['GMV 30d', money(v.gmv30)], [L3(['Saldo', 'Balance', 'الرصيد']), money(v.balance)], [L3(['Produk', 'Products', 'منتجات']), fN(v.products)]].map(k => `<div class="kpi"><div class="k">${k[0]}</div><div class="v">${k[1]}</div></div>`).join('')}</div><div class="tabs" role="tablist">${VTABS.map(k => `<a class="tab" role="tab" aria-selected="${k === tab}" href="#/vendor/${v.id}${k === 'identity' ? '' : '/' + k}">${esc(lbl[k])}</a>`).join('')}</div><div style="margin-top:14px">${gate(body)}</div></div>` }; }
