/* SEGALOKA_CC_BOOKING_API_DIRECTORY_V1 */
let CC_BOOKING_API = { state: 'idle', items: [], pagination: null };
async function ccLoadBookings(query = '', status = '') {
  CC_BOOKING_API = { ...CC_BOOKING_API, state: 'loading' }; rerender();
  try {
    const p = new URLSearchParams({ limit: '100', offset: '0' }); if (query.trim()) p.set('q', query.trim()); if (status) p.set('status', status);
    const response = await fetch('/bff/control-center/bookings?' + p, { credentials: 'same-origin', cache: 'no-store' });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.source !== 'postgresql' || !Array.isArray(result.items)) throw new Error(result.code || 'BOOKING_API_UNAVAILABLE');
    CC_BOOKING_API = { state: 'ready', items: result.items, pagination: result.pagination || null };
  } catch (_) { CC_BOOKING_API = { state: 'error', items: [], pagination: null }; }
  rerender();
}
route('/booking', () => {
  let body = CC_BOOKING_API.state === 'loading' ? stateBlock('loading', { title: 'Memuat Booking', desc: 'Mengambil data resmi dari API Segaloka.' }) : CC_BOOKING_API.state === 'error' ? stateBlock('error', { title: 'Booking tidak tersedia', desc: 'API Booking gagal diakses. Data simulasi tidak ditampilkan.' }) : CC_BOOKING_API.items.length ? '<div class="tbl-wrap"><table class="t"><thead><tr><th>Booking</th><th>Perjalanan</th><th>Status</th><th>Tanggal</th><th class="r">Peserta</th></tr></thead><tbody>' + CC_BOOKING_API.items.map(b => '<tr><td class="mono">' + esc(b.bookingNumber) + '</td><td><b>' + esc((b.departure || {}).title || '—') + '</b><div class="muted">' + esc((b.departure || {}).destination || '—') + '</div></td><td>' + st(b.status) + '</td><td>' + esc(String(b.createdAt || '—')) + '</td><td class="r tnum">' + fN(b.participantCount) + '</td></tr>').join('') + '</tbody></table></div>' : stateBlock('empty', { title: 'Belum ada Booking', desc: 'Tidak ada booking pada sumber data resmi.' });
  const html = '<div class="page">' + phead({ crumbs: [[t('g_book'), '/booking'], [t('booking'), '/booking']], title: L3(['Manajemen Booking','Booking Management','إدارة الحجوزات']), desc: L3(['Daftar booking resmi dari PostgreSQL melalui API Segaloka.','Official bookings from PostgreSQL through the Segaloka API.','قائمة الحجوزات الرسمية من PostgreSQL عبر Segaloka API.']), actions: '<button class="btn" data-act="cc-booking-refresh">' + t('cc_refresh') + '</button>' }) + '<section class="panel"><div class="toolbar"><label class="input">' + ic('search', 'sm') + '<input id="cc-booking-q" type="search" placeholder="' + L3(['Cari nomor booking, judul, tujuan','Search booking number, title, destination','ابحث عن رقم الحجز أو العنوان أو الوجهة']) + '"></label><select id="cc-booking-status" class="select"><option value="">' + t('all') + ' ' + t('status') + '</option><option value="pending">' + L3(['Menunggu','Pending','معلق']) + '</option><option value="confirmed">' + L3(['Dikonfirmasi','Confirmed','مؤكد']) + '</option><option value="cancelled">' + L3(['Dibatalkan','Cancelled','ملغى']) + '</option><option value="completed">' + L3(['Selesai','Completed','مكتمل']) + '</option></select></div>' + body + '</section></div>';
  return { html, mount() { const q = document.getElementById('cc-booking-q'), s = document.getElementById('cc-booking-status'); if (q) q.addEventListener('change', () => ccLoadBookings(q.value, s ? s.value : '')); if (s) s.addEventListener('change', () => ccLoadBookings(q ? q.value : '', s.value)); if (CC_BOOKING_API.state === 'idle') ccLoadBookings(); } };
});
A['cc-booking-refresh'] = () => ccLoadBookings();
route('/booking/:id', p => { const b = bookingById(p.id); if (!b) return { html: `<div class="page">${stateBlock('noresult', { title: L3(['Booking tidak ditemukan', 'Booking not found', 'الحجز غير موجود']), desc: p.id })}</div>` }; const pk = pkgById(b.pkg), tr = travelById(b.travel), trv = TRAVELERS.find(x => x.id === b.traveler); const pays = PAYMENTS.filter(x => x.booking === b.id); const exc = BK_EXC.includes(b.state) ? b.state : null; const cp = b.campaign ? campById(b.campaign) : null; const cv = CONVERSATIONS.find(c => c.booking === b.id);
  const html = `<div class="page">${crumbs([[t('g_book'), '/booking'], [L3(['Booking', 'Booking', 'الحجز']), '/booking'], [b.id, '']])}<div class="phead"><div class="ttl"><h1 class="mono" style="font-family:var(--font-mono)">${b.id}</h1><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:8px">${st(b.state)}<span class="chip">${b.pax} ${L3(['orang', 'pax', 'أشخاص'])}</span><span class="chip mono">${b.payMode}</span><span class="chip">${esc(b.source)}</span></div></div><div class="actions">${cv ? `<a class="btn" href="#/omni/inbox/${cv.id}">${ic('msg')}${L3(['Percakapan', 'Conversation', 'المحادثة'])}</a>` : ''}${(b.paid && !['refunded', 'refund_requested', 'cancelled'].includes(b.state) ? permBtn('booking.manage', ic('undo') + L3(['Refund', 'Refund', 'استرداد']), `data-act="bk-refund" data-id="${b.id}" data-mut`, '') : '')}${(BK_EXC.includes(b.state) || ['departed', 'completed'].includes(b.state) ? '' : permBtn('booking.manage', ic('ban') + L3(['Batalkan', 'Cancel', 'إلغاء']), `data-act="bk-cancel" data-id="${b.id}" data-mut`, 'badb'))}</div></div>
  <section class="panel" style="padding:12px 14px;margin-bottom:14px"><div class="eyebrow" style="margin-bottom:8px">${L3(['Siklus booking', 'Booking lifecycle', 'دورة الحجز'])}</div>${lifeBar(BK_FLOW, exc ? (b.paid ? 'confirmed' : 'awaiting_payment') : b.state, exc)}</section>
  <div class="grid g12"><div class="c7" style="display:grid;gap:14px;align-content:start">${pnl(L3(['Relasi', 'Relations', 'العلاقات']), `<a class="linkcard" href="#/traveler">${ic('user')}<span class="body"><b>${esc(trv.name)}</b><span class="mono">${trv.id}</span></span>${st(trv.passport)}</a><a class="linkcard" href="#/travel/${tr.id}">${ic('building')}<span class="body"><b>${esc(tr.name)}</b><span class="mono">${tr.id}</span></span></a><a class="linkcard" href="#/marketplace/packages">${ic('package')}<span class="body"><b>${esc(pk.name)}</b><span>${money(pk.price)} × ${b.pax} · ${fD(pk.dep)}</span></span>${st(pk.state)}</a>${cp ? `<a class="linkcard" href="#/ads/campaign/${cp.id}">${ic('target')}<span class="body"><b>${esc(cp.name)}</b><span>Attributed campaign</span></span></a>` : ''}<div class="grid g3" style="gap:8px;margin-top:6px">${[['manifest', 'list', 'Manifest', '/booking/manifest'], ['room', 'bed', 'Room List', '/booking/rooms'], ['docs', 'folder', L3(['Dokumen', 'Documents', 'المستندات']), '/booking/documents']].map(x => `<a class="linkcard" href="#${x[3]}" style="margin:0">${ic(x[1])}<span class="body"><b>${x[2]}</b></span></a>`).join('')}</div>`, { icon: 'link' })}${pnl('Payment', `<div class="kpi" style="padding:0;border:0"><div class="v">${money(b.paid, true)} <small class="muted" style="font-size:13px">/ ${money(b.total, true)}</small></div></div><div class="meter ${b.paid >= b.total ? 'ok' : ''}" style="margin:8px 0 12px"><i style="width:${b.paid / b.total * 100}%"></i></div>${pays.map(x => `<a class="linkcard" href="#/finance/payment/${x.id}">${ic('card')}<span class="body"><b class="mono">${x.id}</b><span>${money(x.amount, true)} · ${x.provider} · ${x.channel}</span></span>${st(x.status)}${st(x.recon)}</a>`).join('') || '<span class="muted">—</span>'}`, { icon: 'wallet' })}</div>
  <div class="c5">${pnl(t('timeline'), `<ul class="tl">${[['created', b.created, 'info', 'Checkout · ' + b.source], ...pays.map(x => ['payment ' + x.status + ' · ' + x.id, x.ts, x.status === 'paid' ? 'ok' : x.status === 'pending' ? 'warn' : 'bad', x.provider]), ...(b.paid >= b.total ? [['confirmed', pays[0] ? pays[0].ts + 3e3 : b.created, 'ok', 'Auto · lunas']] : []), ...(exc ? [[exc, b.created + 5 * D, 'bad', 'Admin / Traveler']] : [])].sort((a, c) => c[1] - a[1]).map(h => `<li><span class="dotc ${h[2]}"></span><b class="mono" style="font-weight:550;font-size:12.5px">${esc(h[0])}</b><div class="m">${esc(fDT(h[1]))} · ${esc(h[3])}</div></li>`).join('')}</ul>`, { icon: 'history' })}</div></div></div>`; return { html }; });

