  'cv-send': el => sendMsg(el.dataset.id),
  'cv-tpl': el => popAt(el, `<div class="menu" style="max-width:360px"><div class="mh">${t('template')}</div>${TEMPLATES.map((x, i) => `<button class="mi" data-act="cv-tpl-pick" data-i="${i}" style="align-items:flex-start;flex-direction:column;gap:2px"><b>${esc(x[0])}</b><span class="muted" style="font-size:12px;white-space:normal">${esc(x[1].slice(0, 90))}…</span></button>`).join('')}</div>`, 'start'),
  'cv-tpl-pick': el => { const c = CONVERSATIONS.find(x => x.id === OMNI.active); const txt = TEMPLATES[+el.dataset.i][1].replace('{nama}', c.contact.split(' ')[0]); closeOverlays(); const ta = document.getElementById('cv-text'); ta.value = txt; ta.focus(); },
  'cv-attach': () => toast('info', L3(['Lampiran', 'Attachment', 'مرفق']), L3(['File diunggah ke storage & dipindai malware sebelum dikirim.', 'Files are uploaded to storage & malware-scanned before sending.', 'يتم الفحص قبل الإرسال.'])),
  'cv-ai': () => { const c = CONVERSATIONS.find(x => x.id === OMNI.active); const ta = document.getElementById('cv-text'); ta.value = c.booking ? `Waalaikumsalam ${c.contact.split(' ')[0]}, kami sudah cek booking ${c.booking}. Status saat ini: ${L3(STATUS[bookingById(c.booking).state].slice(2))}. Kami bantu tindak lanjuti hari ini ya.` : `Waalaikumsalam, terima kasih atas minatnya. Untuk paket yang ditanyakan masih tersedia seat. Boleh kami kirimkan detail itinerary & harga?`; ta.focus(); toast('info', 'Segaloka AI', L3(['Draf saran — tinjau sebelum kirim. AI tidak mengirim atas nama Anda.', 'Suggested draft — review before sending. AI never sends on your behalf.', 'مسودة مقترحة — راجعها.'])); },
  'cv-assign': el => { const c = CONVERSATIONS.find(x => x.id === el.dataset.id); popAt(el, `<div class="menu"><div class="mh">Assign</div>${AGENTS.map(a => `<button class="mi" role="menuitemradio" aria-checked="${c.assignee === a.id}" data-act="cv-assign-pick" data-a="${a.id}"><span style="width:7px;height:7px;border-radius:50%;background:${a.online ? 'var(--ok)' : 'var(--ink-3)'}"></span>${esc(a.name)}<span class="muted" style="font-size:11.5px;margin-inline-start:auto">${a.load} open</span></button>`).join('')}<div class="sep"></div><button class="mi" data-act="cv-assign-pick" data-a="">${ic('x', 'sm')}Unassign</button></div>`); },
  'cv-assign-pick': el => { if (!can('omni.assign')) { closeOverlays(); toast('warn', t('no_perm_action'), 'omni.assign'); return; } const c = CONVERSATIONS.find(x => x.id === OMNI.active); c.assignee = el.dataset.a || null; const ag = AGENTS.find(a => a.id === c.assignee); c.messages.push({ dir: 'sys', text: ag ? 'Assigned → ' + ag.name + ' · oleh Admin Pusat' : 'Unassigned · oleh Admin Pusat', ts: nowTs() }); audit('Admin Pusat', 'conversation.assign', 'Conversation/' + c.id, 'success', { after: ag ? ag.name : 'unassigned' }); closeOverlays(); redrawConv(); OMNI.drawList(); toast('ok', ag ? 'Assigned · ' + ag.name : 'Unassigned', c.id); },
