const vprodForm = [{ k: 'name', label: L3(['Nama', 'Name', 'الاسم']), req: true }, { k: 'vendor', label: 'Vendor', type: 'select', options: () => VENDORS.map(v => [v.id, v.name]) }, { k: 'cat', label: L3(['Kategori', 'Category', 'الفئة']), type: 'select', options: VENDOR_CATS }, { k: 'price', label: L3(['Harga (Rp)', 'Price (Rp)', 'السعر']), type: 'number', req: true, min: 0 }, { k: 'unit', label: 'Unit', def: '/pax' }, { k: 'allot', label: 'Allotment', type: 'number', def: 50 }];
route('/vendor/products', () => resPage({ id: 'vprod', nav: 'vendor_prod', noun: 'Produk', desc: L3(['Katalog produk & layanan vendor. Draft → Review → Published → Unpublished → Archived.', 'Vendor product & service catalogue. Draft → Review → Published → Unpublished → Archived.', 'كتالوج المنتجات.']), data: VPRODUCTS, states: ['draft', 'review', 'published', 'unpublished', 'archived'], lifecycle: ['draft', 'review', 'published', 'unpublished', 'archived'], cols: vprodCols, form: vprodForm, make: v => ({ id: 'VP-' + (40100 + VPRODUCTS.length * 3), ...v, state: 'draft' }), acts: vprodActs, kpis: () => ['published', 'review', 'draft', 'unpublished'].map(s => ({ k: L3(STATUS[s].slice(2)), v: fN(VPRODUCTS.filter(p => p.state === s).length) })) }));
route('/affiliate/referral', () => resPage({ id: 'ref', nav: 'aff_ref', noun: 'Referral', desc: L3(['Link & kode referral per Affiliate per Travel. Satu Affiliate boleh punya link ke banyak Travel.', 'Referral links & codes per Affiliate per Travel. One Affiliate may link to many Travels.', 'روابط الإحالة.']), data: REFLINKS, states: ['active', 'paused'], newLabel: L3(['Buat link', 'Create link', 'إنشاء رابط']),
  cols: [{ k: 'name', label: 'Kode', render: r => `<span class="chip mono">${esc(r.name)}</span>` }, { k: 'aff', label: 'Affiliate', render: r => esc(AFFILIATES.find(a => a.id === r.aff).name) }, { k: 'travel', label: 'Travel', render: r => trvLink(r.travel) }, { k: 'url', label: 'URL', render: r => `<span class="mono" style="font-size:11.5px">${esc(r.url)}</span> <button class="btn sm ghost" data-act="copy" data-v="${esc(r.url)}" aria-label="Copy">${ic('copy', 'sm')}</button>` }, { k: 'clicks', label: 'Klik', cls: 'r tnum', render: r => fN(r.clicks) }, { k: 'conv', label: 'Konversi', cls: 'r tnum' }, { k: 'state', label: t('status'), render: r => st(r.state) }],
  form: [{ k: 'aff', label: 'Affiliate', type: 'select', options: () => AFFILIATES.map(a => [a.id, a.name]) }, { k: 'travel', label: 'Travel', type: 'select', options: travelOpts }],
  make: v => { const a = AFFILIATES.find(x => x.id === v.aff); if (!a.travels.includes(v.travel)) a.travels.push(v.travel); return { id: 'REF-' + (8100 + REFLINKS.length * 3), name: a.code + '-' + v.travel.slice(4), ...v, url: travelById(v.travel).website + '/?ref=' + a.code, clicks: 0, conv: 0, state: 'active' }; },
  acts: r => [r.state === 'active' ? { label: t('pause'), to: 'paused', tone: 'warnb' } : { label: t('resume'), to: 'active', tone: 'primary' }] }));
route('/affiliate/commission', () => resPage({ id: 'com', nav: 'aff_com', noun: 'Komisi', desc: L3(['Komisi dihitung dari booking terbayar. Approved → dibayar lewat Withdrawal Affiliate.', 'Commission is computed from paid bookings. Approved → paid via Affiliate Withdrawal.', 'تُحسب العمولة من الحجوزات المدفوعة.']), data: COMMISSIONS, states: ['pending', 'approved', 'paid', 'rejected'], create: false, bulk: [{ k: 'export', label: 'Export' }],
  kpis: () => [{ k: 'Pending', v: money(COMMISSIONS.filter(c => c.state === 'pending').reduce((s, c) => s + c.amount, 0)) }, { k: 'Approved', v: money(COMMISSIONS.filter(c => c.state === 'approved').reduce((s, c) => s + c.amount, 0)) }, { k: 'Paid', v: money(COMMISSIONS.filter(c => c.state === 'paid').reduce((s, c) => s + c.amount, 0)) }, { k: L3(['Rata-rata rate', 'Avg rate', 'متوسط']), v: (() => { const L = COMMISSIONS.filter(c => c.rate != null); return L.length ? pct(L.reduce((s, c) => s + c.rate, 0) / L.length) : '—'; })() }],
  cols: [{ k: 'aff', label: 'Affiliate', render: r => esc(AFFILIATES.find(a => a.id === r.aff).name) }, { k: 'booking', label: 'Booking', render: r => `<a class="mono" href="#/booking/${r.booking}">${r.booking}</a> ${st(bookingById(r.booking).state)}` }, { k: 'travel', label: 'Travel', render: r => trvLink(r.travel) }, { k: 'rate', label: 'Rate', cls: 'r tnum', render: r => r.rate + '%' }, { k: 'amount', label: L3(['Komisi', 'Commission', 'العمولة']), cls: 'r tnum', render: r => money(r.amount, true) }, { k: 'state', label: t('status'), render: r => st(r.state) }],
  acts: r => ({ pending: [{ label: t('approve'), to: 'approved', tone: 'primary', why: ['refunded', 'cancelled', 'failed', 'awaiting_payment'].includes(bookingById(r.booking).state) ? L3(['Booking belum terbayar / dibatalkan', 'Booking unpaid / cancelled', 'الحجز غير مدفوع']) : null }, { label: t('reject'), to: 'rejected', tone: 'badb', reason: true }], approved: [{ label: L3(['Bayar via withdrawal', 'Pay via withdrawal', 'الدفع']), to: 'paid', tone: 'primary', fn: x => WITHDRAWALS.unshift({ id: 'WD-' + (58000 + WITHDRAWALS.length), party: AFFILIATES.find(a => a.id === x.aff).name, partyType: 'Affiliate', ref: x.aff, amount: x.amount, state: 'pending', basis: 'Komisi ' + x.id, ts: nowTs() }), msg: L3(['Withdrawal dibuat → menunggu approval Finance', 'Withdrawal created → awaiting Finance approval', 'تم إنشاء السحب']) }] })[r.state] || [] }));
route('/affiliate/performance', () => { const rows = AFFILIATES.slice().sort((a, b) => b.gmv - a.gmv); return { html: `<div class="page">${phead({ crumbs: [[t('g_eko'), '/affiliate'], ['Affiliate', '/affiliate'], [t('aff_perf'), '']], title: t('aff_perf'), desc: L3(['Leaderboard & kontribusi Affiliate ke GMV lintas Travel.', 'Affiliate leaderboard & GMV contribution across Travels.', 'لوحة الصدارة.']), actions: periodSel() })}${kpiRow([{ k: 'Klik', v: fC(rows.reduce((s, a) => s + a.clicks, 0)) }, { k: 'Konversi', v: fN(rows.reduce((s, a) => s + a.conv, 0)) }, { k: 'CVR', v: pct(rows.reduce((s, a) => s + a.conv, 0) / rows.reduce((s, a) => s + a.clicks, 0) * 100, 2) }, { k: 'GMV', v: money(rows.reduce((s, a) => s + a.gmv, 0)) }])}<div class="grid g2" style="margin-top:14px">${pnl('GMV per Affiliate', hbars(rows.map(a => [a.name, a.gmv]), v => money(v)), { icon: 'bars' })}${pnl(L3(['Travel per Affiliate', 'Travels per Affiliate', 'الشركات لكل مسوق']), hbars(rows.map(a => [a.name, a.travels.length]), fN, 'var(--s3)'), { icon: 'link' })}</div><section class="panel" style="margin-top:14px"><div class="tbl-wrap"><table class="t"><thead><tr><th>#</th><th>Affiliate</th><th class="r">Klik</th><th class="r">Konversi</th><th class="r">CVR</th><th class="r">GMV</th><th class="r">Komisi</th></tr></thead><tbody>${rows.map((a, i) => `<tr><td class="tnum">${i + 1}</td><td>${ent(a.name, a.type, a.color)}</td><td class="r tnum">${fN(a.clicks)}</td><td class="r tnum">${a.conv}</td><td class="r tnum">${pct(a.conv / a.clicks * 100, 2)}</td><td class="r tnum">${money(a.gmv)}</td><td class="r tnum">${money(a.commission)}</td></tr>`).join('')}</tbody></table></div></section></div>` }; });

