  if (tab === 'finance') return `<div class="grid g3">${pnl(L3(['Saldo tersedia', 'Available balance', 'الرصيد']), `<div class="kpi" style="padding:0;border:0"><div class="v">${money(v.balance)}</div><div class="d">${L3(['dari order selesai', 'from completed orders', 'من الطلبات'])}</div></div>`, { icon: 'wallet' })}${pnl(L3(['Dalam proses', 'In progress', 'قيد المعالجة']), `<div class="kpi" style="padding:0;border:0"><div class="v">${money(VORDERS.filter(o => o.vendor === v.id && ['pending', 'confirmed'].includes(o.state)).reduce((s, o) => s + o.value, 0))}</div><div class="d">${L3(['order belum selesai', 'orders not completed', 'غير مكتملة'])}</div></div>`, { icon: 'clock' })}${pnl(L3(['Fee marketplace', 'Marketplace fee', 'رسوم السوق']), `<div class="kpi" style="padding:0;border:0"><div class="v">${money(VORDERS.filter(o => o.vendor === v.id && o.state === 'completed').reduce((s, o) => s + o.value * .05, 0))}</div><div class="d">5% · <a href="#/finance/fee">${L3(['Biaya & Komisi', 'Fee & Commission', 'الرسوم والعمولة'])}</a></div></div>`, { icon: 'percent' })}</div><p class="muted" style="font-size:12.5px">${L3(['Pembayaran vendor melalui Segaloka; withdrawal mengikuti transaksi/pembelian yang selesai.', 'Vendor payments go through Segaloka; withdrawals follow completed transactions/purchases.', 'السحب يتبع المعاملات.'])}</p>`;
