  if (tab === 'activity') { const L = AUDIT.filter(a => a.resource.includes(v.id)); return pnl(L3(['Aktivitas', 'Activity', 'النشاط']), `<ul class="tl">${[...L.map(a => [a.action, a.ts, a.result === 'failed' ? 'bad' : 'ok', a.actor]), ['vendor.created', v.joined, 'neu', L3(['Orientasi', 'Onboarding', 'تهيئة'])]].map(h => `<li><span class="dotc ${h[2]}"></span><b class="mono" style="font-weight:550;font-size:12.5px">${esc(h[0])}</b><div class="m">${esc(h[3])} · ${esc(fDT(h[1]))}</div></li>`).join('')}</ul>`, { icon: 'history' }); }
