/* =====================================================================
   ALUR NYATA v9
   1) Paket Travel: dibuat & dipublish langsung oleh Travel (tanpa approval admin).
   2) Pendaftar: Travel melihat data lengkap jamaah, bukti bayar, dan dokumen yang
      diunggah; memverifikasi / menolak dengan alasan (jamaah diberi tahu).
   3) Withdrawal: diajukan → disetujui / dikembalikan (revisi) / ditahan / ditolak →
      dikirim lagi / dibatalkan → ditransfer (dengan bukti transfer). Saldo ikut nyata.
   File disimpan di tabel control_center.files; metadata di koleksi `uploads`.
   ===================================================================== */
const UPLOADS = [];
const FILECACHE = {};
const DOC_KINDS = [['ktp', ['KTP', 'ID card (KTP)', 'الهوية']], ['passport', ['Paspor', 'Passport', 'الجواز']], ['photo', ['Pas foto 4×6', 'Photo 4×6', 'صورة']], ['kk', ['Kartu Keluarga / Buku Nikah', 'Family card / Marriage book', 'دفتر العائلة']], ['vaccine', ['Sertifikat vaksin meningitis', 'Meningitis vaccine certificate', 'شهادة التطعيم']], ['visa', ['Visa', 'Visa', 'التأشيرة']]];
const docLabel = k => { const d = DOC_KINDS.find(x => x[0] === k); return d ? L3(d[1]) : k === 'payproof' ? L3(['Bukti bayar', 'Payment proof', 'إثبات الدفع']) : k === 'wdproof' ? L3(['Bukti transfer', 'Transfer proof', 'إثبات التحويل']) : k; };
function reroute(pattern, fn) { for (let i = ROUTES.length - 1; i >= 0; i--) if (ROUTES[i].pattern === pattern) ROUTES.splice(i, 1); route(pattern, fn); }

/* ---------- skema tambahan (idempoten, sekali per database) ---------- */
const SCHEMA_V = 3;
async function sbSchemaUpgrade() {
  const r = await sql(`select value #>> '{}' as v from control_center.settings where key = 'schema_version'`).catch(() => []);
  if (+(r[0] && r[0].v) >= SCHEMA_V) return;
  await sql(['begin',
    `create table if not exists control_center.files (id text primary key, ref text, kind text, name text, mime text, size int, data text not null, created_at timestamptz not null default now())`,
    'create index if not exists files_ref_idx on control_center.files (ref)',
    'alter table control_center.files enable row level security',
    'revoke all on control_center.files from anon, authenticated',
    `do $x$ declare c text; begin for c in select conname from pg_constraint where conrelid = 'control_center.withdrawals'::regclass and contype = 'c' and pg_get_constraintdef(oid) ilike '%status%' loop execute format('alter table control_center.withdrawals drop constraint %I', c); end loop; end $x$`,
    `alter table control_center.withdrawals add constraint withdrawals_status_check check (status in ('pending','approved','processing','disbursed','hold','needs_revision','rejected','cancelled'))`,
    `insert into control_center.settings (key, value) values ('schema_version', '${SCHEMA_V}'::jsonb) on conflict (key) do update set value = excluded.value, updated_at = now()`,
    'commit'].join('; ') + ';');
}

/* ---------- unggah & lihat file ---------- */
const MAX_FILE = 4 * 1024 * 1024;
function pickFile(accept) { return new Promise(res => { const i = document.createElement('input'); i.type = 'file'; i.accept = accept || 'image/*,.pdf'; i.onchange = () => res(i.files[0] || null); i.click(); }); }
const readAsDataURL = f => new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(r.result); r.onerror = rej; r.readAsDataURL(f); });
async function fileToData(f) {
  if (/^image\//.test(f.type) && !/svg/.test(f.type)) {
    const url = await readAsDataURL(f); const img = await new Promise((res, rej) => { const im = new Image(); im.onload = () => res(im); im.onerror = rej; im.src = url; });
    const k = Math.min(1, 1600 / Math.max(img.width, img.height)); const c = document.createElement('canvas'); c.width = Math.round(img.width * k); c.height = Math.round(img.height * k); c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
    const d = c.toDataURL('image/jpeg', .82); return { mime: 'image/jpeg', data: d.split(',')[1], size: Math.round(d.length * .75) };
  }
  if (f.size > MAX_FILE) throw new Error(L3(['File terlalu besar (maks 4 MB)', 'File too large (max 4 MB)', 'الملف كبير']));
  const d = await readAsDataURL(f); return { mime: f.type || 'application/octet-stream', data: d.split(',')[1], size: f.size };
}
/* simpan file + metadata; dipakai semua portal */
async function saveUpload(file, meta) {
  const x = await fileToData(file); const up = Object.assign({ id: uid('UPL'), name: file.name || 'file', mime: x.mime, size: x.size, state: 'submitted', ts: nowTs() }, meta);
  if (typeof SB !== 'undefined' && SB.on) await sql(`insert into control_center.files (id, ref, kind, name, mime, size, data) values (${dq(up.id)}, ${dq(up.ref || '')}, ${dq(up.kind)}, ${dq(up.name)}, ${dq(up.mime)}, ${up.size}, ${dq(x.data)})`);
  FILECACHE[up.id] = 'data:' + x.mime + ';base64,' + x.data;
  UPLOADS.unshift(up); return up;
}
async function fileURL(id) {
  if (FILECACHE[id]) return FILECACHE[id];
  if (typeof SB === 'undefined' || !SB.on) return null;
  const r = await sql(`select mime, data from control_center.files where id = ${dq(id)}`); if (!r[0]) return null;
  return FILECACHE[id] = 'data:' + r[0].mime + ';base64,' + r[0].data;
}
A['file-view'] = async el => { const up = UPLOADS.find(u => u.id === el.dataset.id); if (!up) return; modal({ title: docLabel(up.kind) + ' · ' + up.name, wide: true, body: `<div id="fv-box" style="min-height:200px;display:grid;place-items:center">${L3(['Memuat…', 'Loading…', 'جارٍ التحميل…'])}</div>` });
  try { const u = await fileURL(up.id); const box = document.getElementById('fv-box'); if (!box) return; if (!u) { box.innerHTML = stateBlock('empty', { title: L3(['File tidak ditemukan', 'File not found', 'غير موجود']) }); return; }
    box.innerHTML = (/^image\//.test(up.mime) ? `<img src="${u}" alt="${esc(up.name)}" style="max-width:100%;max-height:70vh;border-radius:8px">` : /pdf/.test(up.mime) ? `<embed src="${u}" type="application/pdf" style="width:100%;height:70vh">` : `<div class="muted">${esc(up.mime)}</div>`) + `<div style="margin-top:10px"><button class="btn sm" data-act="file-dl" data-id="${up.id}" hidden id="fv-dl">${ic('download', 'sm')}${L3(['Unduh', 'Download', 'تنزيل'])}</button></div>`;
  const dl = document.getElementById('fv-dl'); if (dl && window.claude && window.claude.use && await window.claude.use('downloads')) dl.hidden = false; }
  catch (e) { toast('bad', L3(['Gagal membuka file', 'Failed to open file', 'فشل']), String(e.message || e)); } };
const upState = u => u.state === 'verified' ? st('verified') : u.state === 'rejected' ? st('rejected') : st('submitted');
const upRow = (u, actions) => `<div class="docrow"><span class="fi">${/pdf/.test(u.mime) ? 'PDF' : 'IMG'}</span><span class="body"><b>${esc(docLabel(u.kind))}${u.pax != null ? ' · ' + L3(['Jamaah ', 'Pilgrim ', 'معتمر ']) + (u.pax + 1) : ''}</b><span>${esc(u.name)} · ${fN(Math.round(u.size / 1024))} KB · ${rel(u.ts)}${u.by ? ' · ' + esc(u.by) : ''}${u.reason ? ' · “' + esc(u.reason) + '”' : ''}</span></span>${upState(u)}<button class="btn sm ghost" data-act="file-view" data-id="${u.id}">${ic('eye', 'sm')}${L3(['Lihat', 'View', 'عرض'])}</button>${actions || ''}</div>`;

/* ================= 1) PAKET: publish langsung oleh Travel ================= */
const canPublish = (tr, p) => { if (p.private) return L3(['Paket khusus SegaDeals — hanya untuk pemesan', 'SegaDeals custom package — for the booker only', 'باقة خاصة']); if (tr.op !== 'active') return L3(['Tenant belum aktif', 'Tenant not active', 'غير نشط']); if (!licOk(tr, p.cat)) return L3(['Izin ', 'Licence ', 'الترخيص ']) + licFor[p.cat] + L3([' belum terverifikasi', ' not verified', ' غير موثق']); if (tr.sub && ['suspended', 'expired', 'cancelled'].includes(tr.sub.state)) return 'Subscription ' + stLbl(tr.sub.state); return null; };
