  'pay-confirm': el => { const u = UPLOADS.find(x => x.id === el.dataset.id); const x = u && PAYMENTS.find(y => y.id === u.payment); const b = x && bookingById(x.booking); if (!b) return;
    confirmAction({ title: L3(['Konfirmasi pembayaran ', 'Confirm payment ', 'تأكيد الدفع ']) + x.id, desc: L3(['Pastikan dana ', 'Make sure ', 'تأكد ']) + '<b>' + money(x.amount, true) + '</b>' + L3([' sudah masuk ke rekening. Booking akan diperbarui otomatis.', ' has arrived in the account. The booking updates automatically.', ' وصل.']), label: L3(['Konfirmasi lunas', 'Confirm paid', 'تأكيد']), reason: false, resource: 'Payment/' + x.id, onOk: () => {
      u.state = 'verified'; u.reviewedAt = nowTs(); x.status = 'paid'; x.ts = nowTs(); x.channel = x.channel || 'Transfer manual'; x.proof = u.id; b.paid = Math.min(b.total, b.paid + x.amount); const prev = b.state; b.state = b.paid >= b.total ? 'confirmed' : 'partially_paid';
      if (b.state === 'partially_paid' && !PAYMENTS.some(y => y.booking === b.id && y.status === 'pending')) PAYMENTS.unshift({ id: uid('PAY'), booking: b.id, travel: b.travel, payer: b.traveler, amount: b.total - b.paid, provider: x.provider, channel: 'Transfer manual', ref: (x.ref || 'TRF') + '-2', status: 'pending', ts: nowTs(), recon: 'pending', flow: b.payMode, fee: 0 });
      pAudit('travel', 'payment.proof.confirm', 'Payment/' + x.id, { before: prev, after: b.state }); partyNotify([ntKey('traveler', b.traveler)], 'payment', 'ok', L3(['Pembayaran diterima', 'Payment received', 'تم استلام الدفع']), x.id + ' · ' + money(x.amount), { traveler: '/p/traveler/bookings/' + b.id }); recompute(); toast('ok', L3(['Pembayaran dikonfirmasi', 'Payment confirmed', 'تم التأكيد']), 'Booking → ' + stLbl(b.state)); rerender(); } }); }
