/* =====================================================================
   SETELAH BERANGKAT: tidak ada refund, hanya ulasan.
   - Booking berstatus Berangkat / Selesai tidak bisa dibatalkan atau direfund
     (dijaga di semua pintu: admin, Travel, aplikasi pengguna).
   - Pengguna memberi rating & ulasan untuk Travel dan paket yang dipilih.
   - Travel membalas ulasan; admin dapat menyembunyikan ulasan yang melanggar.
   ===================================================================== */
const REVIEWS = [];
const NO_REFUND = ['departed', 'completed'];
const refundBlocked = b => b && NO_REFUND.includes(b.state);
const blockMsg = () => toast('warn', L3(['Tidak bisa refund / batal', 'Refund / cancel not allowed', 'لا يمكن الاسترداد']), L3(['Jamaah sudah berangkat — yang tersedia hanya ulasan.', 'The pilgrim has departed — only a review is available.', 'بعد السفر: التقييم فقط.']));
['bk-cancel', 'bk-refund'].forEach(k => { const f = A[k]; if (f) A[k] = el => { if (refundBlocked(bookingById(el.dataset.id))) return blockMsg(); return f(el); }; });
if (A['pay-refund']) { const f = A['pay-refund']; A['pay-refund'] = el => { const p = PAYMENTS.find(x => x.id === el.dataset.id); if (p && refundBlocked(bookingById(p.booking))) return blockMsg(); return f(el); }; }

/* pengguna: ajukan pembatalan/refund (hanya sebelum berangkat) */
A['u-cancel'] = el => { const u = me('traveler'); const b = bookingById(el.dataset.id); if (!b || b.traveler !== u.id) return; if (refundBlocked(b)) return blockMsg(); if (BK_EXC.includes(b.state)) return;
  confirmAction({ title: (b.paid ? L3(['Ajukan refund', 'Request refund', 'طلب استرداد']) : L3(['Batalkan booking', 'Cancel booking', 'إلغاء الحجز'])) + ' · ' + b.id, desc: b.paid ? L3(['Dana ', 'Your ', 'المبلغ ']) + '<b>' + money(b.paid, true) + '</b>' + L3([' akan diproses refund sesuai kebijakan Travel. Travel & Finance akan meninjau.', ' will be refunded per the Travel’s policy after review.', ' سيُراجع.']) : L3(['Seat dilepas dan tagihan dibatalkan.', 'Seats are released and invoices cancelled.', 'تُحرر المقاعد.']), tone: 'danger', label: b.paid ? L3(['Ajukan refund', 'Request refund', 'طلب']) : L3(['Batalkan', 'Cancel', 'إلغاء']), resource: 'Booking/' + b.id, onOk: r => {
    const prev = b.state; b.prevState = prev; b.state = b.paid ? 'refund_requested' : 'cancelled'; PAYMENTS.filter(x => x.booking === b.id && x.status === 'pending').forEach(x => x.status = 'expired');
    if (b.paid) REFUNDS.unshift({ id: uid('RF'), booking: b.id, travel: b.travel, amount: b.paid, reason: r, state: 'pending', ts: nowTs(), by: u.name });
    recompute(); audit(u.name, b.paid ? 'booking.refund_request' : 'booking.cancel', 'Booking/' + b.id, 'success', { source: 'Aplikasi Pengguna', before: prev, after: b.state, reason: r });
    pNotif('booking', 'warn', b.paid ? L3(['Permintaan refund', 'Refund request', 'طلب استرداد']) : L3(['Booking dibatalkan pengguna', 'Booking cancelled by user', 'أُلغي']), b.id + ' · ' + u.name, '/booking/' + b.id);
    partyNotify([ntKey('travel', b.travel), b.mitra && ntKey('mitra', b.mitra), b.agen && ntKey('agen', b.agen)], 'payment', 'warn', b.paid ? L3(['Pengajuan refund dari jamaah', 'Refund request from pilgrim', 'طلب استرداد']) : L3(['Booking dibatalkan jamaah', 'Booking cancelled by pilgrim', 'أُلغي']), b.id + ' · ' + u.name + (b.paid ? ' · ' + money(b.paid) + ' · ' + r : ''), { travel: '/p/travel/bookings/' + b.id });
    toast('ok', stLbl(b.state), b.id); rerender(); } }); };

/* ---------- ulasan ---------- */
const stars = (n, size) => `<span aria-label="${n}/5" style="color:#F5A524;letter-spacing:1px;font-size:${size || 14}px">${'★'.repeat(Math.round(n || 0))}<span style="color:var(--line-strong)">${'★'.repeat(5 - Math.round(n || 0))}</span></span>`;
const pubReviews = () => REVIEWS.filter(r => r.state !== 'hidden');
const avgOf = (L, k) => L.length ? Math.round(L.reduce((s, r) => s + (+r[k] || 0), 0) / L.length * 10) / 10 : null;
const reviewOf = b => REVIEWS.find(r => r.booking === b.id);
const RATE_OPTS = [[5, '★★★★★ · 5'], [4, '★★★★ · 4'], [3, '★★★ · 3'], [2, '★★ · 2'], [1, '★ · 1']];
function reviewCard(r, opts) { opts = opts || {}; const tr = travelById(r.travel) || {}; const pk = pkgById(r.pkg) || {};
  return `<div style="border:1px solid var(--line);border-radius:10px;padding:12px;margin-bottom:10px${r.state === 'hidden' ? ';opacity:.55' : ''}"><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b>${esc(trvName(r.traveler))}</b><span class="muted" style="font-size:12px">${rel(r.ts)}${r.edited ? ' · ' + L3(['diubah', 'edited', 'معدل']) : ''}</span><span style="flex:1"></span>${r.state === 'hidden' ? st('inactive') : ''}</div>
  <div style="display:flex;gap:14px;flex-wrap:wrap;margin-top:6px;font-size:12.5px"><span>Travel ${stars(r.rTravel)}</span><span>${L3(['Paket', 'Package', 'الباقة'])} ${stars(r.rPkg)}</span></div>
  ${opts.showPkg ? `<div class="muted" style="font-size:12px;margin-top:4px">${esc(tr.name || '')} · ${esc(pk.name || '')}</div>` : ''}
  <p style="margin:8px 0 0;white-space:pre-wrap">${esc(r.text)}</p>
  ${r.reply ? `<div style="margin-top:10px;padding:8px 10px;border-inline-start:3px solid var(--accent);background:var(--surface-2);border-radius:6px;font-size:13px"><b>${esc(tr.name || 'Travel')}</b> <span class="muted" style="font-size:11.5px">${rel(r.replyTs)}</span><br>${esc(r.reply)}</div>` : ''}
  ${r.state === 'hidden' && r.hideReason ? `<div class="muted" style="font-size:12px;margin-top:6px">${L3(['Disembunyikan: ', 'Hidden: ', 'مخفي: ']) + esc(r.hideReason)}</div>` : ''}
  ${opts.actions || ''}</div>`; }
const RV_FORM = r => [{ k: 'rTravel', label: L3(['Rating Travel', 'Travel rating', 'تقييم الشركة']), type: 'select', options: RATE_OPTS, def: r ? r.rTravel : 5 }, { k: 'rPkg', label: L3(['Rating paket', 'Package rating', 'تقييم الباقة']), type: 'select', options: RATE_OPTS, def: r ? r.rPkg : 5 }, { k: 'text', label: L3(['Ulasan Anda', 'Your review', 'تقييمك']), type: 'textarea', req: true, def: r ? r.text : '' }];
Object.assign(A, {
  'rv-new': el => { const u = me('traveler'); const b = bookingById(el.dataset.id); if (!b || b.traveler !== u.id || !refundBlocked(b)) return; const r = reviewOf(b);
    modal({ title: (r ? L3(['Ubah ulasan', 'Edit review', 'تعديل']) : L3(['Beri ulasan', 'Write a review', 'اكتب تقييماً'])) + ' · ' + ((pkgById(b.pkg) || {}).name || ''), body: fields(RV_FORM(r), 'rv-') + `<p class="muted" style="font-size:12px;margin:6px 0 0">${L3(['Ulasan tampil publik di halaman Travel & paket, atas nama Anda.', 'Your review is shown publicly on the Travel & package pages under your name.', 'يظهر للعامة.'])}</p>`, foot: `<button class="btn" data-act="close">${t('cancel')}</button><button class="btn primary" data-act="rv-save" data-id="${b.id}">${ic('send', 'sm')}${L3(['Kirim ulasan', 'Submit review', 'إرسال'])}</button>` }); },
  'rv-save': el => { const u = me('traveler'); const b = bookingById(el.dataset.id); if (!b || !refundBlocked(b)) return; const v = formVals(RV_FORM().map(f => ({ k: f.k, req: f.req })), 'rv-'); if (!v) return; if (String(v.text).trim().length < 10) { document.getElementById('rv-text').style.borderColor = 'var(--bad)'; toast('warn', L3(['Ulasan terlalu singkat', 'Review too short', 'قصير جداً']), L3(['Minimal 10 karakter', 'At least 10 characters', '10 أحرف'])); return; }
    let r = reviewOf(b); const isNew = !r; if (!r) { r = { id: uid('REV'), booking: b.id, traveler: u.id, travel: b.travel, pkg: b.pkg, ts: nowTs(), state: 'published' }; REVIEWS.unshift(r); } else { r.edited = nowTs(); }
    Object.assign(r, { rTravel: +v.rTravel, rPkg: +v.rPkg, text: String(v.text).trim() }); recompute();
    audit(u.name, isNew ? 'review.create' : 'review.update', 'Review/' + r.id, 'success', { source: 'Aplikasi Pengguna', after: r.rTravel + '★ travel · ' + r.rPkg + '★ paket' });
    partyNotify([ntKey('travel', b.travel)], 'marketplace', r.rTravel >= 4 ? 'ok' : r.rTravel <= 2 ? 'bad' : 'info', (isNew ? L3(['Ulasan baru ', 'New review ', 'تقييم جديد ']) : L3(['Ulasan diubah ', 'Review updated ', 'تم التعديل '])) + '★'.repeat(r.rTravel), trvName(u.id) + ' · ' + r.text.slice(0, 80), { travel: '/p/travel/reviews' });
    closeOverlays(); toast('ok', L3(['Terima kasih atas ulasan Anda', 'Thanks for your review', 'شكراً لتقييمك']), ''); rerender(); },
  'rv-reply': el => { const r = REVIEWS.find(x => x.id === el.dataset.id); if (!r) return; modal({ title: L3(['Balas ulasan', 'Reply to review', 'الرد']), body: reviewCard(r) + fields([{ k: 'reply', label: L3(['Balasan Anda (publik)', 'Your reply (public)', 'ردك']), type: 'textarea', req: true, def: r.reply || '' }], 'rr-'), foot: `<button class="btn" data-act="close">${t('cancel')}</button><button class="btn primary" data-act="rv-reply-go" data-id="${r.id}">${L3(['Kirim balasan', 'Send reply', 'إرسال'])}</button>` }); },
  'rv-reply-go': el => { const r = REVIEWS.find(x => x.id === el.dataset.id); const tr = me('travel'); if (!r || r.travel !== tr.id) return; const v = formVals([{ k: 'reply', req: true }], 'rr-'); if (!v) return; r.reply = v.reply.trim(); r.replyTs = nowTs(); pAudit('travel', 'review.reply', 'Review/' + r.id); partyNotify([ntKey('traveler', r.traveler)], 'marketplace', 'info', tr.name + L3([' membalas ulasan Anda', ' replied to your review', ' رد على تقييمك']), r.reply.slice(0, 80), { traveler: '/p/traveler/bookings/' + r.booking }); closeOverlays(); toast('ok', L3(['Balasan terkirim', 'Reply sent', 'أُرسل']), ''); rerender(); },
  'rv-mod': el => { const r = REVIEWS.find(x => x.id === el.dataset.id); if (!r) return; const hide = r.state !== 'hidden'; confirmAction({ title: (hide ? L3(['Sembunyikan ulasan', 'Hide review', 'إخفاء']) : L3(['Tampilkan lagi', 'Show again', 'إظهار'])) + ' · ' + r.id, desc: esc(r.text.slice(0, 160)), tone: hide ? 'danger' : 'primary', reason: hide, resource: 'Review/' + r.id, onOk: reason => { r.state = hide ? 'hidden' : 'published'; r.hideReason = hide ? reason : ''; recompute(); audit('Admin Pusat', hide ? 'review.hide' : 'review.show', 'Review/' + r.id, 'success', { reason }); if (hide) partyNotify([ntKey('traveler', r.traveler), ntKey('travel', r.travel)], 'marketplace', 'warn', L3(['Ulasan disembunyikan admin', 'Review hidden by admin', 'أُخفي التقييم']), reason, { traveler: '/p/traveler/bookings/' + r.booking, travel: '/p/travel/reviews' }); toast('ok', stLbl(hide ? 'inactive' : 'active'), r.id); rerender(); } }); }
});

