  let s = typeof p === 'string' ? p : p && typeof p.result === 'string' ? p.result : JSON.stringify(p);
  const m = s.match(/\n<untrusted-data-[^>]*>\n([\s\S]*?)\n<\/untrusted-data/) || s.match(/<untrusted-data-[^>]*>\s*(\[[\s\S]*?\])\s*<\/untrusted-data/); if (m) s = m[1];
