async function sql(q) {
  throw new Error('Legacy Supabase SQL connector disabled'); const r = await SB.mcp.callTool('Supabase', 'execute_sql', { project_id: SB.project, query: q }, { cache: false }); return parseRows(r.payload !== undefined ? r.payload : (r.content && r.content[0] && r.content[0].text)); }
const snap = o => JSON.stringify(o);
function replaceInPlace(o, d) { Object.keys(o).forEach(k => delete o[k]); Object.assign(o, d); }
function applyRows(rows, remote) { let changed = 0; const by = {}; rows.forEach(r => (by[r.c] = by[r.c] || []).push(r)); ALLC().forEach(([name, get]) => { const L = by[name]; if (!L) return; const arr = get(); const idx = new Map(arr.map(o => [o.id, o])); SB.saved[name] = SB.saved[name] || {}; if (!remote) { arr.length = 0; L.forEach(r => { arr.push(r.data); SB.saved[name][r.id] = snap(r.data); }); changed += L.length; return; } L.forEach(r => { const cur = idx.get(r.id); const j = snap(r.data); if (cur) { if (snap(cur) === SB.saved[name][r.id] && snap(cur) !== j) { const before = JSON.parse(snap(cur)); replaceInPlace(cur, r.data); SB.saved[name][r.id] = j; changed++; SB.changes.push({ name, id: r.id, before, after: r.data }); } } else { arr.unshift(r.data); SB.saved[name][r.id] = j; changed++; SB.changes.push({ name, id: r.id, before: null, after: r.data }); } }); }); return changed; }
const auditFromRow = r => ({ id: r.id, ts: +r.t, actor: r.actor, action: r.action, resource: r.resource, result: r.result, source: r.source, before: r.before, after: r.after, reason: r.reason });
async function sbLoad() {
  const core = Object.keys(CORE).map(k => `select '${k}' as c, id, data from control_center.${k}`).join(' union all ');
  const [a, b, c, d, pr] = await Promise.all([sql(core), sql(`select collection as c, id, data from control_center.records`), sql(`select key, value from control_center.settings`), sql(`select id, (extract(epoch from ts)*1000)::bigint as t, actor, action, resource, result, source, before, after, reason from control_center.audit_log where not is_demo order by ts desc limit 400`), sql(PROBE_SQL()).catch(() => [])]);
  SB.seen = +((pr && pr[0] && pr[0].m) || 0);
  applyRows([...a, ...b], false);
  c.forEach(r => { if (SETS[r.key]) { SETS[r.key][1](r.value); SB.savedSet[r.key] = snap(SETS[r.key][0]()); } });
  AUDIT.length = 0; d.forEach(r => { AUDIT.push(auditFromRow(r)); SB.auditSaved.add(r.id); });
  syncTpl(); SB.lastPoll = Date.now();
}
function buildFlush() {
  if (typeof ntScan === 'function') ntScan();
  const stmts = []; const commit = [];
  ALLC().forEach(([name, get, core]) => { const saved = SB.saved[name] = SB.saved[name] || {}; const cur = {}; const up = []; get().forEach(o => { if (!o || !o.id) return; const j = snap(o); cur[o.id] = j; if (saved[o.id] !== j) up.push(o); }); const del = Object.keys(saved).filter(id => !(id in cur));
    if (up.length) { const js = dq(JSON.stringify(up)); stmts.push(core ? `insert into control_center.${name} (id, data, is_demo) select x->>'id', x, ${SB.seeding} from jsonb_array_elements(${js}::jsonb) x on conflict (id) do update set data = excluded.data, updated_at = now()` : `insert into control_center.records (collection, id, data, is_demo) select '${name}', x->>'id', x, ${SB.seeding} from jsonb_array_elements(${js}::jsonb) x on conflict (collection, id) do update set data = excluded.data, updated_at = now()`); }
    if (del.length) { const js = dq(JSON.stringify(del)); stmts.push(core ? `delete from control_center.${name} where id in (select jsonb_array_elements_text(${js}::jsonb))` : `delete from control_center.records where collection = '${name}' and id in (select jsonb_array_elements_text(${js}::jsonb))`); }
    if (up.length || del.length) commit.push(() => { up.forEach(o => saved[o.id] = snap(o)); del.forEach(id => delete saved[id]); }); });
  Object.entries(SETS).forEach(([k, [get]]) => { const j = snap(get()); if (SB.savedSet[k] !== j) { stmts.push(`insert into control_center.settings (key, value) values ('${k}', ${dq(j)}::jsonb) on conflict (key) do update set value = excluded.value, updated_at = now()`); commit.push(() => SB.savedSet[k] = j); } });
  const newA = AUDIT.filter(a => !SB.auditSaved.has(a.id));
  if (newA.length) { stmts.push(`insert into control_center.audit_log (id, ts, actor, action, resource, result, source, before, after, reason, is_demo) select x->>'id', to_timestamp((x->>'ts')::double precision/1000), x->>'actor', x->>'action', x->>'resource', coalesce(x->>'result','success'), x->>'source', x->>'before', x->>'after', x->>'reason', ${SB.seeding} from jsonb_array_elements(${dq(JSON.stringify(newA))}::jsonb) x on conflict (id) do nothing`); commit.push(() => newA.forEach(a => SB.auditSaved.add(a.id))); }
  return { stmts, commit };
}
async function sbFlush() {
  if (!SB.on) return; if (SB.busy) { SB.again = true; return; }
  const { stmts, commit } = buildFlush(); if (!stmts.length) return;
  SB.busy = true; SB.state = 'saving'; paintSync();
  try { await sql('begin; ' + stmts.join('; ') + '; commit;'); commit.forEach(f => f()); SB.state = 'saved'; SB.lastSave = Date.now(); SB.err = null; rtEmit(stmts.length); }
  catch (e) { SB.state = 'error'; SB.err = e; if (!SB.errToast) { SB.errToast = true; toast('bad', L3(['Gagal menyimpan ke Supabase', 'Failed to save to Supabase', 'فشل الحفظ']), sbErrText(e)); } }
  SB.busy = false; paintSync(); if (SB.again) { SB.again = false; setTimeout(sbFlush, 300); }
}
async function sbPoll(force) {
  if (!SB.on || SB.busy || (document.hidden && !force) || SB.polling) return; SB.polling = true; try { await sbPollInner(); } finally { SB.polling = false; }
}
async function sbPollInner() { const since = SB.lastPoll - 5000; const ts = `to_timestamp(${since / 1000})`;
  try { const q = Object.keys(CORE).map(k => `select '${k}' as c, id, data from control_center.${k} where updated_at > ${ts}`).join(' union all ') + ` union all select collection, id, data from control_center.records where updated_at > ${ts}`; const [rows, aud, sets] = await Promise.all([sql(q), sql(`select id, (extract(epoch from ts)*1000)::bigint as t, actor, action, resource, result, source, before, after, reason from control_center.audit_log where inserted_at > ${ts} order by ts desc`), sql(`select key, value from control_center.settings where updated_at > ${ts}`)]);
    SB.lastPoll = Date.now(); let n = applyRows(rows, true); aud.forEach(r => { if (!SB.auditSaved.has(r.id)) { AUDIT.unshift(auditFromRow(r)); SB.auditSaved.add(r.id); n++; } }); AUDIT.sort((a, b) => b.ts - a.ts);
    sets.forEach(r => { if (SETS[r.key] && snap(SETS[r.key][0]()) === SB.savedSet[r.key]) { SETS[r.key][1](r.value); SB.savedSet[r.key] = snap(SETS[r.key][0]()); n++; } });
    if (n) { syncTpl(); announce(); if (ovl().innerHTML) SB.pendingRemote = true; else { rerender(); renderTop(); } const u = document.getElementById('sync-pill'); if (u) u.classList.add('pulse'); }
    if (SB.state === 'error') { SB.state = 'saved'; paintSync(); }
  } catch (e) { SB.state = 'error'; SB.err = e; paintSync(); }
}
function sbErrText(e) { const c = e && e.code; return ({ needs_reauth: L3(['Hubungkan ulang Supabase di Settings → Connectors', 'Reconnect Supabase in Settings → Connectors', 'أعد ربط Supabase']), server_not_connected: L3(['Tambahkan connector Supabase di Settings → Connectors', 'Add the Supabase connector in Settings → Connectors', 'أضف Supabase']), not_in_manifest: L3(['Akses Supabase untuk halaman ini ditolak', 'Supabase access declined for this page', 'تم رفض الوصول']), server_unavailable: L3(['Supabase sedang tidak dapat dijangkau', 'Supabase is unreachable right now', 'غير متاح']), tool_error: (e.message || '').slice(0, 160), empty: e.message, denied: e.message })[c] || (e && e.message ? String(e.message).slice(0, 160) : 'Unknown error'); }
function paintSync() { const el = document.getElementById('sync-pill'); if (!el) return; const m = { connecting: ['info', L3(['Menghubungkan…', 'Connecting…', 'جارٍ الاتصال…'])], saving: ['info', L3(['Menyimpan…', 'Saving…', 'جارٍ الحفظ…'])], saved: ['ok', 'Live · ' + L3(['tersimpan', 'saved', 'محفوظ']) + (SB.peers > 1 ? ' · ' + SB.peers + ' ' + L3(['online', 'online', 'متصل']) : '')], error: ['bad', L3(['Gagal sinkron', 'Sync failed', 'فشل المزامنة'])], local: ['warn', L3(['Mode demo lokal', 'Local demo mode', 'وضع محلي'])] }[SB.state]; el.className = 'envpill sync-' + m[0]; el.querySelector('.envtext').textContent = m[1]; }
A['sync-info'] = el => popAt(el, `<div class="menu" style="max-width:340px;padding:12px"><b>${SB.on ? 'Supabase · ' + SB.project : L3(['Mode demo lokal', 'Local demo mode', 'وضع محلي'])}</b><p class="muted" style="font-size:12.5px;margin:6px 0 10px">${SB.on ? L3(['Data dibaca & disimpan di Postgres melalui connector Supabase Anda. Realtime: layar lain yang terbuka diberi tahu seketika; perubahan dari luar terdeteksi ±3 detik.', 'Data is read & saved in Postgres through your Supabase connector. Realtime: other open screens are notified instantly; outside changes are detected within ~3s.', 'البيانات في Postgres.']) : esc(SB.err ? sbErrText(SB.err) : L3(['Connector Supabase tidak tersedia untuk viewer ini — perubahan tidak disimpan.', 'Supabase connector unavailable for this viewer — changes are not saved.', 'غير متصل.']))}</p><dl class="dl" style="font-size:12px"><dt>${t('status')}</dt><dd>${esc(SB.state)}</dd><dt>${L3(['Simpan terakhir', 'Last save', 'آخر حفظ'])}</dt><dd>${SB.lastSave ? fDT(SB.lastSave) : '—'}</dd><dt>${L3(['Tarik terakhir', 'Last pull', 'آخر سحب'])}</dt><dd>${SB.lastPoll ? fDT(SB.lastPoll) : '—'}</dd></dl>${SB.on ? `<button class="btn sm" style="margin-top:10px" data-act="sync-now">${ic('refresh', 'sm')}${L3(['Sinkron sekarang', 'Sync now', 'مزامنة'])}</button>` : `<button class="btn sm" style="margin-top:10px" data-act="sync-retry">${ic('refresh', 'sm')}${t('retry')}</button>`}</div>`);
A['sync-now'] = async () => { /* SEGALOKA_CC_SYNC_SAFETY_V1 */ closeOverlays(); toast('warn', 'Sinkronisasi belum tersedia', 'Control Center belum terhubung ke API Segaloka.'); };
A['sync-retry'] = () => { closeOverlays(); toast('warn', 'Koneksi belum tersedia', 'API Segaloka belum terhubung ke Control Center.'); };
let flushT = null; const scheduleFlush = () => { clearTimeout(flushT); flushT = setTimeout(sbFlush, 900); };
['click', 'change'].forEach(ev => document.addEventListener(ev, () => { if (SB.on) scheduleFlush(); }, true));
document.addEventListener('keyup', e => { if (SB.on && e.key === 'Enter') scheduleFlush(); });
/* v6: iklan hanya di inventori Segaloka (web + app). Data lama (Meta/Google/TikTok/WA/Email) dipetakan ke slot internal. Idempoten. */
function migrateAdsInventory() { let n = 0; const map = ch => AD_LEGACY[ch] || ch;
  CAMPAIGNS.forEach(c => { const nx = [...new Set((c.channels || []).map(map))].filter(ch => AD_CHANNELS.includes(ch)); if (JSON.stringify(nx) !== JSON.stringify(c.channels)) { c.channels = nx.length ? nx : ['Web · Sponsored Pencarian']; n++; } if (c.name === 'SegaDeals Flash — Oktober') { c.name = 'SegaDeals — Ajukan Permintaan Umrah'; n++; } if (c.landing === 'wa' || c.landing === 'web') { c.landing = c.landing === 'wa' ? 'chat' : 'travel'; n++; } });
  ADSETS.forEach(a => { if (AD_LEGACY[a.channel]) { a.channel = AD_LEGACY[a.channel]; n++; } });
  APPROVALS.forEach(a => (a.ctx || []).forEach(x => { if (x[0] === 'Channel' && typeof x[1] === 'string' && Object.keys(AD_LEGACY).some(k => x[1].includes(k))) { x[1] = [...new Set(x[1].split(', ').map(map))].join(', '); n++; } }));
  if (PLACEMENTS.some(p => !AD_CHANNELS.includes(p.name)) || PLACEMENTS.length !== AD_CHANNELS.length) { PLACEMENTS.length = 0; AD_CHANNELS.forEach((ch, i) => PLACEMENTS.push({ id: 'PLC-' + (1 + i), name: ch, kind: AD_SURF(ch), account: PLC_SLOT[ch], campaigns: CAMPAIGNS.filter(c => c.channels.includes(ch) && c.state === 'active').length, state: 'active' })); n++; }
  if (TRACKERS.some(x => /Meta|Google|TikTok/.test(x.name + x.dest)) || !TRACKERS.some(x => x.name.includes('SegaDeals'))) { const keep = TRACKERS.filter(x => !/Meta|Google|TikTok/.test(x.name + x.dest)); const add = [['TRK-W1', 'Event web · segaloka.com', 'Website Segaloka', 'ad_impression, ad_click, view_package, lead'], ['TRK-A1', 'Event aplikasi · SDK Segaloka', 'Aplikasi Segaloka', 'ad_impression, ad_click, view_package, lead'], ['TRK-SD', 'Server events · SegaDeals', 'Segaloka backend', 'segadeals.request, segadeals.offer, segadeals.accept']].filter(x => !keep.some(k => k.name === x[1])).map(x => ({ id: x[0], name: x[1], dest: x[2], events: x[3], state: 'active', match: 99 })); TRACKERS.length = 0; TRACKERS.push(...add.slice(0, 2), ...keep, ...add.slice(2)); n++; }
  const ren = { 'Meta (Ads + WhatsApp BSP)': ['WhatsApp Business (BSP)', 'Omnichannel'], 'Google Ads': ['Ad server Segaloka (web + app)', 'Ads · internal'], 'TikTok Ads': ['Push & in-app messaging (App)', 'Aplikasi Segaloka'] };
  INTEGS.forEach(x => { if (ren[x.name]) { [x.name, x.kind] = ren[x.name]; if (x.state === 'inactive') x.state = 'active'; n++; } });
  AUTOMATIONS.forEach(x => { if (/Click-to-Chat/.test(x.trigger || '')) { x.trigger = 'Chat in-app dari iklan Segaloka'; n++; } }); RULES.forEach(x => { if (/Click-to-Chat/.test(x.name || '')) { x.name = 'Chat in-app dari campaign'; x.channel = 'Web Chat'; n++; } });
  FLAGS.forEach(x => { if (x.name === 'ads.tiktok') { x.id = 'ads.app_inbox'; x.name = 'ads.app_inbox'; x.desc = 'Placement Notifikasi In-App (Aplikasi Segaloka)'; n++; } if (x.name === 'mp.segadeals_v2' && /countdown/.test(x.desc)) { x.desc = 'SegaDeals v2 (permintaan pengguna → penawaran Travel)'; x.rollout = 100; n++; } });
  return n; }
const SB_MIGRATION = "-- SEGALOKA Control Center \u00b7 schema v1\n-- Dipisah di schema `control_center` agar tidak mengubah skema produk di `public`.\ncreate schema if not exists control_center;\nrevoke all on schema control_center from anon, authenticated;\n-- Setiap entitas disimpan sebagai dokumen jsonb (sumber kebenaran untuk UI) + kolom bertipe\n-- yang di-generate dari dokumen (untuk query, index, dan constraint aturan bisnis).\n\ncreate or replace function control_center.sg_doc_table(t text, cols text) returns void language plpgsql as $f$\nbegin\n  execute format('create table if not exists control_center.%I (\n    id text primary key,\n    data jsonb not null check (jsonb_typeof(data) = ''object'' and data->>''id'' = id),\n    is_demo boolean not null default false,\n    created_at timestamptz not null default now(),\n    updated_at timestamptz not null default now()%s)', t, cols);\n  execute format('create index if not exists %I on control_center.%I (updated_at)', t || '_updated_idx', t);\n  execute format('alter table control_center.%I enable row level security', t);\n  execute format('revoke all on control_center.%I from anon, authenticated', t);\nend $f$;\n\nselect control_center.sg_doc_table('travels', $c$,\n  name text generated always as (data->>'name') stored,\n  city text generated always as (data->>'city') stored,\n  status text generated always as (data->>'op') stored check (status in ('active','review','inactive')),\n  legal_status text generated always as (data->>'legal') stored check (legal_status in ('draft','submitted','under_review','verified','expiring','rejected','expired')),\n  payment_mode text generated always as (data->>'payMode') stored check (payment_mode in ('DIRECT_TO_TRAVEL','VIA_SEGALOKA')),\n  plan text generated always as (data#>>'{sub,plan}') stored,\n  subscription_state text generated always as (data#>>'{sub,state}') stored check (subscription_state in ('pending','trial','active','grace','suspended','expired','cancelled')),\n  branch_quota int generated always as ((data#>>'{branch,quota}')::int) stored check (branch_quota >= 2)$c$);\n\n-- Mitra Travel terikat ke tepat SATU Travel (kolom tunggal, wajib).\nselect control_center.sg_doc_table('mitra', $c$,\n  name text generated always as (data->>'name') stored,\n  travel_id text generated always as (data->>'travel') stored not null,\n  status text generated always as (data->>'status') stored$c$);\n\nselect control_center.sg_doc_table('vendors', $c$,\n  name text generated always as (data->>'name') stored,\n  verification text generated always as (data->>'verif') stored check (verification in ('draft','submitted','under_review','verified','rejected')),\n  status text generated always as (data->>'status') stored$c$);\n\n-- Affiliate boleh terhubung ke banyak Travel (array), terpisah dari Vendor & Mitra.\nselect control_center.sg_doc_table('affiliates', $c$,\n  name text generated always as (data->>'name') stored,\n  code text generated always as (data->>'code') stored,\n  status text generated always as (data->>'status') stored$c$);\n\nselect control_center.sg_doc_table('travelers', $c$,\n  name text generated always as (data->>'name') stored$c$);\n\nselect control_center.sg_doc_table('packages', $c$,\n  name text generated always as (data->>'name') stored,\n  travel_id text generated always as (data->>'travel') stored,\n  category text generated always as (data->>'cat') stored,\n  price numeric generated always as ((data->>'price')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('draft','review','published','unpublished','archived'))$c$);\n\nselect control_center.sg_doc_table('bookings', $c$,\n  travel_id text generated always as (data->>'travel') stored,\n  traveler_id text generated always as (data->>'traveler') stored,\n  package_id text generated always as (data->>'pkg') stored,\n  total numeric generated always as ((data->>'total')::numeric) stored,\n  paid numeric generated always as ((data->>'paid')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('created','awaiting_payment','partially_paid','confirmed','processing','ready','departed','completed','cancelled','refund_requested','refunded','failed'))$c$);\n\nselect control_center.sg_doc_table('payments', $c$,\n  booking_id text generated always as (data->>'booking') stored,\n  travel_id text generated always as (data->>'travel') stored,\n  amount numeric generated always as ((data->>'amount')::numeric) stored,\n  provider text generated always as (data->>'provider') stored,\n  flow text generated always as (data->>'flow') stored check (flow in ('DIRECT_TO_TRAVEL','VIA_SEGALOKA')),\n  status text generated always as (data->>'status') stored check (status in ('pending','paid','failed','expired','refunded')),\n  recon_status text generated always as (data->>'recon') stored check (recon_status in ('pending','reconciled','unmatched','mismatch'))$c$);\n\nselect control_center.sg_doc_table('settlements', $c$,\n  travel_id text generated always as (data->>'travel') stored,\n  net numeric generated always as ((data->>'net')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('scheduled','processing','settled','hold','failed'))$c$);\n\nselect control_center.sg_doc_table('withdrawals', $c$,\n  party_type text generated always as (data->>'partyType') stored check (party_type in ('Vendor','Travel','Affiliate')),\n  amount numeric generated always as ((data->>'amount')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('pending','approved','disbursed','hold','rejected'))$c$);\n\nselect control_center.sg_doc_table('refunds', $c$,\n  booking_id text generated always as (data->>'booking') stored,\n  amount numeric generated always as ((data->>'amount')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('pending','refunded','rejected'))$c$);\n\nselect control_center.sg_doc_table('campaigns', $c$,\n  name text generated always as (data->>'name') stored,\n  owner_travel_id text generated always as (data->>'owner') stored,\n  budget numeric generated always as ((data->>'budget')::numeric) stored,\n  spent numeric generated always as ((data->>'spent')::numeric) stored,\n  status text generated always as (data->>'state') stored check (status in ('draft','review','scheduled','active','paused','completed','archived'))$c$);\n\nselect control_center.sg_doc_table('conversations', $c$,\n  channel text generated always as (data->>'channel') stored,\n  contact text generated always as (data->>'contact') stored,\n  assignee text generated always as (data->>'assignee') stored,\n  status text generated always as (data->>'status') stored check (status in ('open','pending','resolved','closed'))$c$);\n\nselect control_center.sg_doc_table('approvals', $c$,\n  domain text generated always as (data->>'domain') stored,\n  type text generated always as (data->>'type') stored,\n  priority text generated always as (data->>'priority') stored check (priority in ('p1','p2','p3')),\n  risk int generated always as ((data->>'risk')::int) stored,\n  status text generated always as (data->>'status') stored check (status in ('waiting','in_progress','needs_revision','approved','rejected'))$c$);\n\ncreate index if not exists bookings_travel_idx on control_center.bookings (travel_id);\ncreate index if not exists payments_booking_idx on control_center.payments (booking_id);\ncreate index if not exists packages_travel_idx on control_center.packages (travel_id);\ncreate index if not exists approvals_status_idx on control_center.approvals (status, priority);\n\n-- Koleksi lain (konfigurasi, operasional, ads, omnichannel, dsb.)\ncreate table if not exists control_center.records (\n  collection text not null,\n  id text not null,\n  data jsonb not null check (jsonb_typeof(data) = 'object'),\n  is_demo boolean not null default false,\n  name text generated always as (data->>'name') stored,\n  state text generated always as (coalesce(data->>'state', data->>'status')) stored,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  primary key (collection, id)\n);\ncreate index if not exists records_updated_idx on control_center.records (updated_at);\nalter table control_center.records enable row level security;\nrevoke all on control_center.records from anon, authenticated;\n\ncreate table if not exists control_center.settings (\n  key text primary key,\n  value jsonb not null,\n  updated_at timestamptz not null default now()\n);\nalter table control_center.settings enable row level security;\nrevoke all on control_center.settings from anon, authenticated;\n\n-- Audit log: append-only.\ncreate table if not exists control_center.audit_log (\n  id text primary key,\n  ts timestamptz not null,\n  actor text not null,\n  action text not null,\n  resource text not null,\n  result text not null default 'success',\n  source text,\n  before text,\n  after text,\n  reason text,\n  is_demo boolean not null default false,\n  inserted_at timestamptz not null default now()\n);\ncreate index if not exists audit_ts_idx on control_center.audit_log (ts desc);\ncreate index if not exists audit_inserted_idx on control_center.audit_log (inserted_at);\nalter table control_center.audit_log enable row level security;\nrevoke all on control_center.audit_log from anon, authenticated;\n\ncreate or replace function control_center.sg_audit_append_only() returns trigger language plpgsql set search_path = '' as $f$\nbegin raise exception 'audit_log is append-only'; end $f$;\ndrop trigger if exists audit_no_update on control_center.audit_log;\ncreate trigger audit_no_update before update or delete on control_center.audit_log for each row execute function control_center.sg_audit_append_only();\ndrop trigger if exists audit_no_truncate on control_center.audit_log;\ncreate trigger audit_no_truncate before truncate on control_center.audit_log for each statement execute function control_center.sg_audit_append_only();\n\ndrop function control_center.sg_doc_table(text, text);\n\n-- v2: Agen (Travel -> Mitra Travel -> Agen)\ncreate table if not exists control_center.agen (\n  id text primary key,\n  data jsonb not null check (jsonb_typeof(data) = 'object' and data->>'id' = id),\n  is_demo boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  name text generated always as (data->>'name') stored,\n  mitra_id text generated always as (data->>'mitra') stored not null,\n  travel_id text generated always as (data->>'travel') stored not null,\n  status text generated always as (data->>'status') stored check (status in ('active','review','inactive'))\n);\ncreate index if not exists agen_updated_idx on control_center.agen (updated_at);\ncreate index if not exists agen_mitra_idx on control_center.agen (mitra_id);\nalter table control_center.agen enable row level security;\nrevoke all on control_center.agen from anon, authenticated;\ncreate or replace function control_center.sg_agen_check() returns trigger language plpgsql set search_path = '' as $f$\ndeclare mt text;\nbegin\n  select m.data->>'travel' into mt from control_center.mitra m where m.id = new.data->>'mitra';\n  if mt is null then raise exception 'Agen % harus terikat ke Mitra Travel yang ada (mitra=%)', new.id, new.data->>'mitra'; end if;\n  if mt is distinct from new.data->>'travel' then raise exception 'Agen %: travel % tidak sama dengan travel Mitra % (%)', new.id, new.data->>'travel', new.data->>'mitra', mt; end if;\n  return new;\nend $f$;\ndrop trigger if exists agen_hierarchy on control_center.agen;\ncreate trigger agen_hierarchy before insert or update on control_center.agen for each row execute function control_center.sg_agen_check();\ncreate or replace function control_center.sg_mitra_travel_lock() returns trigger language plpgsql set search_path = '' as $f$\nbegin\n  if (old.data->>'travel') is distinct from (new.data->>'travel') and exists (select 1 from control_center.agen a where a.data->>'mitra' = new.id) then\n    raise exception 'Mitra % masih memiliki Agen; Travel tidak dapat diubah', new.id;\n  end if;\n  return new;\nend $f$;\ndrop trigger if exists mitra_travel_lock on control_center.mitra;\ncreate trigger mitra_travel_lock before update on control_center.mitra for each row execute function control_center.sg_mitra_travel_lock();\n";
const isMissing = e => /does not exist|relation .*control_center|schema "control_center"/i.test((e && e.message) || '');
const isDenied = e => /permission|not authorized|forbidden|-32600/i.test((e && e.message) || '');
async function sbBootstrap(firstTime) {
  if (firstTime) { toast('info', L3(['Menyiapkan database…', 'Setting up the database…', 'جارٍ إعداد قاعدة البيانات…']), L3(['Membuat schema control_center', 'Creating control_center schema', 'إنشاء المخطط'])); await sql(SB_MIGRATION); }
  await sql(`insert into control_center.settings (key, value) values ('data_mode', '"production"'::jsonb) on conflict (key) do update set value = excluded.value`);
  SB.on = true; await sbFlush(); if (SB.state === 'error') throw SB.err;
}
/* Produksi: data demo lama dicadangkan ke control_center.demo_backup lalu dihapus (sekali saja). Konfigurasi tetap. */
const ENTITY_RECS = ['branches', 'notifications', 'websites', 'vendor_products', 'referral_links', 'commissions', 'sd_requests', 'sd_offers', 'contacts', 'broadcasts', 'adsets', 'ads', 'creatives', 'ad_budgets', 'vouchers', 'ops_documents', 'deposits', 'leads', 'platform_users', 'security_events', 'risk_cases', 'incidents', 'webhooks', 'bank_lines', 'departures', 'vendor_orders', 'uploads', 'reviews', 'sd_ledger', 'letters', 'reg_fees'];
const CORE_DEL_ORDER = ['approvals', 'conversations', 'campaigns', 'refunds', 'withdrawals', 'settlements', 'payments', 'bookings', 'packages', 'travelers', 'affiliates', 'vendors', 'agen', 'mitra', 'travels'];
async function sbProductionize() {
  const r = await sql(`select value #>> '{}' as v from control_center.settings where key = 'data_mode'`);
  if (r[0] && r[0].v === 'production') return false;
  const n = await sql(`select (select count(*) from control_center.travels) + (select count(*) from control_center.bookings) as n`);
  if (+(n[0] && n[0].n) > 0 && !SB.purgeOk) { SB.needPurge = true; return false; }
  const inList = ENTITY_RECS.map(k => `'${k}'`).join(',');
  await sql(['begin',
    'create table if not exists control_center.demo_backup (tbl text not null, id text not null, data jsonb, backed_at timestamptz not null default now(), primary key (tbl, id))',
    'alter table control_center.demo_backup enable row level security',
    'revoke all on control_center.demo_backup from anon, authenticated',
    ...CORE_DEL_ORDER.map(k => `insert into control_center.demo_backup (tbl, id, data) select '${k}', id, data from control_center.${k} on conflict do nothing`),
    `insert into control_center.demo_backup (tbl, id, data) select 'records:' || collection, id, data from control_center.records where collection in (${inList}) on conflict do nothing`,
    ...CORE_DEL_ORDER.map(k => `delete from control_center.${k}`),
    `delete from control_center.records where collection in (${inList})`,
    `insert into control_center.settings (key, value) values ('data_mode', '"production"'::jsonb) on conflict (key) do update set value = excluded.value`,
    'commit'].join('; ') + ';');
  return true;
}
async function sbConnect() {
  /* SEGALOKA_CC_LEGACY_GUARD_V1 */
  SB.on = false;
  SB.state = 'disconnected';
  SB.err = 'Legacy connector disabled';
  return;
  SB.state = 'connecting'; paintSync();
  let mcp = null; try { mcp = window.claude && window.claude.use ? await window.claude.use('mcp') : null; } catch (e) { mcp = null; }
  if (!mcp || DEMO) { SB.state = 'local'; paintSync(); renderBanners(); return; }
  SB.mcp = mcp;
  try {
    let purged = false; SB.needPurge = false;
    try { purged = await sbProductionize(); await sbLoad(); }
    catch (e) { if (isMissing(e)) { await sbBootstrap(true); await sbLoad(); } else throw e; }
    if (typeof sbSchemaUpgrade === 'function') await sbSchemaUpgrade().catch(e => console.warn('schema upgrade', e));
    SB.on = true; SB.state = 'saved'; SB.err = null;
    if (purged) { clearFakeStats(); recompute(); audit('System', 'database.production', 'Supabase/' + SB.project + '/control_center', 'success', { source: 'Control Center', after: L3(['Data demo dicadangkan ke demo_backup & dihapus', 'Demo data backed up to demo_backup & removed', 'تم نسخ البيانات التجريبية وحذفها']) }); await sbFlush(); toast('ok', L3(['Mode produksi aktif', 'Production mode on', 'وضع الإنتاج']), L3(['Data demo dipindah ke cadangan', 'Demo data moved to backup', 'نُقلت البيانات'])); }
    if (migrateAdsInventory()) { audit('System', 'ads.inventory.migrate', 'Ads/placements', 'success', { source: 'Control Center v6', after: 'Iklan hanya di Website & Aplikasi Segaloka' }); await sbFlush(); }
    if (ensureLinks()) await sbFlush();
    renderShell(); render(); paintSync();
    toast('ok', L3(['Terhubung ke Supabase · realtime aktif', 'Connected to Supabase · realtime on', 'متصل · مباشر']), SB.project);
    rtInit(); setInterval(sbProbe, 3000); setInterval(sbPoll, 30000); document.addEventListener('visibilitychange', () => { if (!document.hidden) { sbFlush(); sbPoll(true); } }); window.addEventListener('online', () => { sbFlush(); sbPoll(true); }); window.addEventListener('focus', () => sbProbe(true)); setInterval(() => { if (SB.pendingRemote && !ovl().innerHTML) { SB.pendingRemote = false; rerender(); } }, 2000);
  } catch (e) { SB.on = false; SB.state = 'local'; SB.err = isDenied(e) ? { code: 'denied', message: L3(['Akun Supabase yang terhubung tidak punya akses ke project ', 'The connected Supabase account has no access to project ', 'لا صلاحية للمشروع ']) + SB.project + L3([' — sambungkan ulang connector Supabase dengan akun pemilik project.', ' — reconnect the Supabase connector with the owning account.', '.']) } : e; paintSync(); renderBanners(); rerender(); }
}


/* ---------- REALTIME ---------- */
function announce() { const C = SB.changes.splice(0); if (!C.length) return; const msgs = []; C.forEach(c => { c.after && SB.flash.add(c.id); const a = c.after, b = c.before;
  if (c.name === 'bookings' && !b) msgs.push(['info', L3(['Booking baru', 'New booking', 'حجز جديد']), a.id + ' · ' + trvName(a.traveler) + ' · ' + a.source, (wsOf() === 'admin' ? '/booking/' : '/p/travel/bookings/') + a.id]);
  else if (c.name === 'approvals' && !b) msgs.push(['warn', L3(['Approval baru', 'New approval', 'موافقة جديدة']), a.title, '/approval/' + a.id]);
  else if (c.name === 'payments' && b && b.status !== 'paid' && a.status === 'paid') msgs.push(['ok', L3(['Pembayaran masuk', 'Payment received', 'دفعة واردة']), a.id + ' · ' + money(a.amount), '/finance/payment/' + a.id]);
  else if (c.name === 'conversations' && (a.messages || []).length > ((b && b.messages) || []).length) { const m = a.messages[a.messages.length - 1]; msgs.push(['info', (m.dir === 'in' ? a.contact : (m.by || 'Travel')), m.text, wsOf() === 'traveler' ? '/p/traveler/chat' : '/omni/inbox/' + a.id]); if (window.OMNI && OMNI.active === a.id) { const ch = document.getElementById('chat'); if (ch) setTimeout(() => { const x = document.getElementById('chat'); if (x) x.scrollTop = x.scrollHeight; }, 50); } }
  else if (c.name === 'notifications' && !b && a.to && typeof myNotifKey === 'function' && a.to === myNotifKey()) msgs.push([a.tone === 'bad' ? 'bad' : a.tone === 'warn' ? 'warn' : a.tone === 'ok' ? 'ok' : 'info', a.title, a.sub, a.route]);
  else if (c.name === 'sd_requests' && !b) msgs.push(['info', L3(['Permintaan SegaDeals baru', 'New SegaDeals request', 'طلب SegaDeals جديد']), sdTitle(a) + ' · ' + a.pax + ' pax', wsOf() === 'travel' ? '/p/travel/segadeals' : '/marketplace/segadeals']);
  else if (c.name === 'sd_offers' && !b) msgs.push(['info', L3(['Penawaran SegaDeals baru', 'New SegaDeals offer', 'عرض جديد']), ((travelById(a.travel) || {}).name || '') + ' · ' + money(a.price) + '/pax', wsOf() === 'traveler' ? '/p/traveler/segadeals/' + a.request : '/marketplace/segadeals']);
  else if (c.name === 'sd_offers' && b && b.state !== a.state && a.state === 'accepted') msgs.push(['ok', L3(['Penawaran Anda dipilih pengguna', 'Your offer was chosen', 'تم اختيار عرضك']), a.request + ' · ' + money(a.price) + '/pax', wsOf() === 'travel' ? '/p/travel/segadeals' : '/marketplace/segadeals']);
  else if (c.name === 'withdrawals' && !b) msgs.push(['info', L3(['Withdrawal baru', 'New withdrawal', 'سحب جديد']), a.party + ' · ' + money(a.amount), '/finance/withdrawal']);
  else if (c.name === 'packages' && b && b.state !== a.state) msgs.push(['info', a.name + ' → ' + L3(STATUS[a.state].slice(2)), (travelById(a.travel) || {}).name || '', a.state === 'review' ? '/marketplace/moderation' : '/p/travel/packages']);
  else if (c.name === 'approvals' && b && b.status !== a.status) msgs.push([a.status === 'approved' ? 'ok' : a.status === 'rejected' ? 'bad' : 'warn', a.title, L3(STATUS[a.status].slice(2)), '/approval/' + a.id]); });
  msgs.slice(0, 3).forEach(m => toast(m[0], m[1], m[2], m[3])); if (msgs.length > 3) toast('info', '+' + (msgs.length - 3) + ' ' + L3(['perubahan lain', 'more changes', 'تغييرات أخرى']), ''); setTimeout(() => { SB.flash.clear(); }, 3500); }
const PROBE_SQL = () => 'select (extract(epoch from greatest(' + [...Object.keys(CORE).map(k => `(select max(updated_at) from control_center.${k})`), '(select max(updated_at) from control_center.records)', '(select max(updated_at) from control_center.settings)', '(select max(inserted_at) from control_center.audit_log)'].join(', ') + '))*1000)::bigint as m';
async function sbProbe(force) { if (!SB.on || SB.busy || SB.polling || (document.hidden && !force)) return; try { const r = await sql(PROBE_SQL()); const m = +(r[0] && r[0].m) || 0; if (!SB.seen) { SB.seen = m; return; } if (m > SB.seen) { SB.seen = m; await sbPoll(true); const ol = document.getElementById('omni-live'); if (ol && typeof omniLoad === 'function') omniLoad(ol.dataset.ch).catch(() => { }); } } catch (e) { } }
async function rtInit() { let room = null; try { room = await window.claude.use('room'); } catch (e) { } if (!room) return; SB.room = room; room.on('sg.changed', msg => { if (msg.sameTab) return; setTimeout(() => sbPoll(true), 150); }); room.onPeers(ch => { SB.peers = ch.peers.length; paintSync(); }); }
function rtEmit(n) { if (SB.room) SB.room.emit('sg.changed', { n }).catch(() => { }); }

/* seed export (dipakai sekali untuk mengisi database) */
function sbExport() { const out = { core: {}, recs: {}, sets: {}, audit: AUDIT }; ALLC().forEach(([n, g, core]) => (core ? out.core : out.recs)[n] = g().filter(o => o && o.id)); Object.entries(SETS).forEach(([k, [g]]) => out.sets[k] = g()); return out; }

/* pembersihan data demo hanya atas konfirmasi pemilik (tidak otomatis) */
A['sb-purge'] = () => confirmAction({ title: L3(['Cadangkan & hapus data demo', 'Back up & remove demo data', 'نسخ وحذف البيانات التجريبية']), desc: L3(['Semua Travel, booking, pembayaran, dan entitas demo lain disalin ke tabel control_center.demo_backup lalu dihapus. Konfigurasi (fee, plan, slot iklan, template) tetap. Setelah ini semua angka dihitung dari data nyata.', 'All demo Travels, bookings, payments and other entities are copied to control_center.demo_backup and then removed. Configuration (fees, plans, ad slots, templates) is kept. Afterwards every figure is computed from real data.', 'سيتم النسخ ثم الحذف.']), tone: 'danger', reason: true, label: L3(['Cadangkan & hapus', 'Back up & remove', 'نسخ وحذف']), resource: 'Supabase/' + SB.project, onOk: async () => { SB.purgeOk = true; try { await sbProductionize(); ENTITY_ARRAYS().forEach(a => { a.length = 0; }); SB.saved = {}; await sbLoad(); clearFakeStats(); SB.needPurge = false; audit('Admin Pusat', 'database.production', 'Supabase/' + SB.project + '/control_center', 'success', { source: 'Control Center', after: 'demo data -> demo_backup' }); await sbFlush(); rtEmit(1); toast('ok', L3(['Mode produksi aktif', 'Production mode on', 'وضع الإنتاج']), L3(['Data demo dipindah ke cadangan', 'Demo data moved to backup', 'نُقلت'])); renderBanners(); rerender(); } catch (e) { toast('bad', L3(['Gagal', 'Failed', 'فشل']), String(e.message || e)); } } });

/* Finance is unavailable until an official Segaloka ledger exists. Keep the V7 shell/layout,
   but never expose seeded financial arrays or mutation controls as real data. */
function financeUnavailablePage() {
  const content = stateBlock('empty', {
    title: L3(['Data keuangan belum tersedia', 'Financial data is not available', 'البيانات المالية غير متاحة']),
    desc: L3([
      'Belum ada ledger keuangan resmi pada API dan PostgreSQL Segaloka. Tidak ada transaksi simulasi yang ditampilkan.',
      'No official financial ledger exists in the Segaloka API and PostgreSQL. Simulated transactions are not shown.',
      'لا يوجد دفتر مالي رسمي في API وقاعدة بيانات Segaloka. لن يتم عرض معاملات محاكاة.'
    ])
  });
  return { html: '<div class="page">' + phead({ crumbs: [[t('g_fin'), '/finance'], [t('fin_ov'), '/finance']], title: t('fin_title'), desc: t('fin_desc') }) + '<section class="panel" style="min-height:260px;display:grid;place-items:center">' + content + '</section></div>' };
}
['/finance', '/finance/transactions', '/finance/gateway', '/finance/settlement', '/finance/withdrawal', '/finance/deposit', '/finance/refund', '/finance/reconciliation', '/finance/fee'].forEach(path => reroute(path, financeUnavailablePage));
reroute('/finance/payment/:id', financeUnavailablePage);
reroute('/finance/withdrawal/:id', financeUnavailablePage);

/* SEGALOKA_CC_AUDIT_LOG_API_V1 */
let CC_AUDIT_API = { state: 'idle', items: [], pagination: null };
async function ccLoadAuditLogs(q = '', offset = 0) {
  CC_AUDIT_API = { ...CC_AUDIT_API, state: 'loading' };
  rerender();
  try {
    const params = new URLSearchParams({ limit: '25', offset: String(Math.max(0, offset)) });
    if (q.trim()) params.set('q', q.trim());
    const response = await fetch('/bff/control-center/audit-logs?' + params, { credentials: 'same-origin', cache: 'no-store' });
    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.source !== 'postgresql' || !Array.isArray(result.items)) throw new Error(result.code || 'AUDIT_LOG_API_UNAVAILABLE');
    CC_AUDIT_API = { state: 'ready', items: result.items, pagination: result.pagination || null };
  } catch (_) {
    CC_AUDIT_API = { state: 'error', items: [], pagination: null };
  }
  rerender();
}
function ccAuditLogPage() {
  const s = CC_AUDIT_API;
  let body = s.state === 'loading' ? stateBlock('loading', { title: 'Memuat Audit Log', desc: 'Mengambil aktivitas resmi dari PostgreSQL.' }) : s.state === 'error' ? stateBlock('error', { title: 'Audit Log tidak tersedia', desc: 'API Audit Log gagal diakses. Data simulasi tidak ditampilkan.' }) : !s.items.length ? stateBlock('empty', { title: 'Belum ada aktivitas', desc: 'Tidak ada audit log pada sumber data resmi.' }) : '<div class="tbl-wrap"><table class="t"><thead><tr><th>Timestamp</th><th>Actor</th><th>Action</th><th>Resource</th><th>Organisasi</th></tr></thead><tbody>' + s.items.map(x => '<tr><td class="tnum">' + esc(fDT(new Date(x.createdAt).getTime())) + '</td><td>' + esc(x.actor) + '</td><td><span class="mono">' + esc(x.action) + '</span></td><td><span class="mono">' + esc((x.entityType || '') + (x.entityId ? '/' + x.entityId : '')) + '</span></td><td>' + esc(x.organization || '—') + '</td></tr>').join('') + '</tbody></table></div>';
  const p = s.pagination || { offset: 0, limit: 25, total: 0 };
  const page = '<div class="toolbar"><label class="input">' + ic('search', 'sm') + '<input id="cc-audit-q" type="search" placeholder="' + L3(['Cari aktor, tindakan, atau resource','Search actor, action, or resource','ابحث عن المنفذ أو الإجراء أو المورد']) + '"></label><span style="flex:1"></span><span class="muted">' + fN(p.total) + ' ' + L3(['total','total','الإجمالي']) + '</span></div>';
  const pager = '<div class="actions" style="justify-content:flex-end;margin-top:12px"><button class="btn sm" data-act="cc-audit-prev" ' + (p.offset <= 0 ? 'disabled' : '') + '>Sebelumnya</button><button class="btn sm" data-act="cc-audit-next" ' + (p.offset + p.limit >= p.total ? 'disabled' : '') + '>Berikutnya</button></div>';
  return { html: '<div class="page">' + phead({ crumbs: [[t('g_comp'), '/compliance/audit'], [t('audit'), '/compliance/audit']], title: t('audit'), desc: L3(['Audit Log resmi dari PostgreSQL. Hanya baca.','Official PostgreSQL Audit Log. Read-only.','سجل التدقيق الرسمي من PostgreSQL. للقراءة فقط.']), actions: '<button class="btn" data-act="cc-audit-refresh">' + t('cc_refresh') + '</button>' }) + '<section class="panel">' + page + body + (s.state === 'ready' ? pager : '') + '</section></div>', mount() { const q = document.getElementById('cc-audit-q'); if (q) q.addEventListener('change', () => ccLoadAuditLogs(q.value, 0)); if (s.state === 'idle') ccLoadAuditLogs(); } };
}
reroute('/compliance/audit', ccAuditLogPage);
A['cc-audit-refresh'] = () => ccLoadAuditLogs(document.getElementById('cc-audit-q')?.value || '', CC_AUDIT_API.pagination?.offset || 0);
A['cc-audit-prev'] = () => ccLoadAuditLogs(document.getElementById('cc-audit-q')?.value || '', Math.max(0, (CC_AUDIT_API.pagination?.offset || 0) - (CC_AUDIT_API.pagination?.limit || 25)));
A['cc-audit-next'] = () => ccLoadAuditLogs(document.getElementById('cc-audit-q')?.value || '', (CC_AUDIT_API.pagination?.offset || 0) + (CC_AUDIT_API.pagination?.limit || 25));

